sum_reduction_cpp_source = """
#include <hip/hip_runtime.h>

#define WARP_SIZE 64
#define MAX_BLOCK_SIZE 1024

__device__ __forceinline__ float warp_reduce_sum(float val) {
    for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
        val += __shfl_down(val, offset);
    }
    return val;
}

__global__ void sum_reduction_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch_size,
    int reduce_dim,
    int other_dim,
    int input_stride_reduce,
    int input_stride_other,
    int output_stride_other
) {
    int batch blockIdx_x = blockIdx.x;
    int other_idx = blockIdx.y * blockDim.x + threadIdx.x;

    if (batch_idx >= batch_size || other_idx >= other_dim) {
        return;
    }

    float sum = 0.0f;

    // Each thread processes chunks of the reduction dimension
    // Linearize access for better memory coalescing
    const float* input_ptr = input + batch_idx * reduce_dim * other_dim + other_idx;

    // Loop over reduction dimension
    for (int i = 0; i < reduce_dim; i++) {
        sum += input_ptr[i * other_dim];
    }

    // Store result
    output[batch_idx * output_stride_other + other_idx] = sum;
}

__global__ void sum_reduction_tiled_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch_size,
    int reduce_dim,
    int other_dim,
    int input_stride_other
) {
    extern __shared__ float sdata[];
    int batch_idx = blockIdx.x;
    int other_idx = blockIdx.y;

    if (batch_idx >= batch_size || other_idx >= other_dim) {
        return;
    }

    int tid = threadIdx.x;

    // Load data into shared memory
    const float* input_ptr = input + batch_idx * reduce_dim * other_dim + other_idx;

    float sum = 0.0f;
    for (int i = tid; i < reduce_dim; i += blockDim.x) {
        sum += input_ptr[i * other_dim];
    }

    sdata[tid] = sum;
    __syncthreads();

    // Reduction in shared memory
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    // Write result
    if (tid == 0) {
        output[batch_idx * other_dim + other_idx] = sdata[0];
    }
}

torch::Tensor sum_reduction_hip(torch::Tensor x, int dim) {
    auto batch_size = x.size(0);
    auto dim1 = x.size(1);
    auto dim2 = x.size(2);

    auto output = torch::zeros({batch_size, 1, dim2}, x.options());

    // Choose block size based on reduction dimension
    int block_size = 256;
    if (dim1 < 64) block_size = 64;
    else if (dim1 < 128) block_size = 128;
    else if (dim1 < 512) block_size = 512;
    else block_size = 256;

    if (dim1 < block_size * 2) {
        // For small reduction dimensions, use parallel reduction
        dim3 blockDim(block_size);
        dim3 gridDim((batch_size + blockDim.x - 1) / blockDim.x, (dim2 + blockDim.y - 1) / blockDim.y);

        // Simple parallel reduction kernel
        int threads_per_element = (dim1 + 31) / 32 * 32;
        threads_per_element = min(threads_per_element, 1024);

        dim3 grid(batch_size, (dim2 + threads_per_element - 1) / threads_per_element);
        dim3 block(threads_per_element);

        if (block.x > 1024) block.x = 1024;

        sum_reduction_kernel<<<grid, block>>>(
            x.data_ptr<float>(),
            output.data_ptr<float>(),
            batch_size,
            dim1,
            dim2,
            dim1 * dim2,  // Not used in this kernel
            dim2,
            dim2
        );
    } else {
        // For larger reduction dimensions, use shared memory reduction
        dim3 grid(batch_size, dim2);
        dim3 block(block_size);

        sum_reduction_tiled_kernel<<<grid, block, block_size * sizeof(float)>>>(
            x.data_ptr<float>(),
            output.data_ptr<float>(),
            batch_size,
            dim1,
            dim2,
            dim2
        );
    }

    return output;
}
"""

sum_reduction = load_inline(
    name="sum_reduction",
    cpp_sources=sum_reduction_cpp_source,
    functions=["sum_reduction_hip"],
    verbose=True,
)


class ModelNew(nn.Module):
    """
    Optimized model with custom HIP kernel for sum reduction.
    """
    def __init__(self, dim: int):
        """
        Initializes the model with the dimension to reduce over.

        Args:
            dim (int): Dimension to reduce over.
        """
        super(ModelNew, self).__init__()
        self.dim = dim
        self.sum_reduction = sum_reduction

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Applies sum reduction over the specified dimension using custom HIP kernel.

        Args:
            x (torch.Tensor): Input tensor of shape (..., dim, ...).

        Returns:
            torch.Tensor: Output tensor after sum reduction, shape (..., 1, ...).
        """
        return self.sum_reduction.sum_reduction_hip(x, self.dim)

