softmax_hip_source = """
#include <hip/hip_runtime.h>

#define WARP_SIZE 64

__device__ __forceinline__ float warp_reduce_max(float val) {
    #pragma unroll
    for (int offset = 32; offset > 0; offset /= 2) {
        val = fmaxf(val, __shfl_down(val, offset));
    }
    return val;
}

__device__ __forceinline__ float warp_reduce_sum(float val) {
    #pragma unroll
    for (int offset = 32; offset > 0; offset /= 2) {
        val += __shfl_down(val, offset);
    }
    return val;
}

__global__ void softmax_kernel(const float* __restrict__ x, float* __restrict__ out, int batch_size, int dim) {
    int row = blockIdx.x;
    if (row >= batch_size) return;

    const float* row_ptr = x + row * dim;
    float* out_ptr = out + row * dim;

    int tid = threadIdx.x;
    int warp_id = tid / WARP_SIZE;
    int lane_id = tid % WARP_SIZE;
    int warps_per_block = blockDim.x / WARP_SIZE;

    // Compute max for numerical stability
    float max_val = -INFINITY;
    for (int i = tid; i < dim; i += blockDim.x) {
        max_val = fmaxf(max_val, row_ptr[i]);
    }
    max_val = warp_reduce_max(max_val);

    // First warp of each block shares max_val using shared memory
    __shared__ float shared_max[WARP_SIZE];
    if (lane_id == 0) shared_max[warp_id] = max_val;
    __syncthreads();
    if (tid < warps_per_block) {
        max_val = shared_max[tid];
        max_val = warp_reduce_max(max_val);
        shared_max[0] = max_val;
    }
    __syncthreads();
    max_val = shared_max[0];

    // Compute sum of exp(x - max)
    float sum_exp = 0.0f;
    for (int i = tid; i < dim; i += blockDim.x) {
        float val = expf(row_ptr[i] - max_val);
        sum_exp += val;
        out_ptr[i] = val;
    }
    sum_exp = warp_reduce_sum(sum_exp);

    // Reduce sum_exp across warps
    __shared__ float shared_sum[WARP_SIZE];
    if (lane_id == 0) shared_sum[warp_id] = sum_exp;
    __syncthreads();
    if (tid < warps_per_block) {
        sum_exp = shared_sum[tid];
        sum_exp = warp_reduce_sum(sum_exp);
        shared_sum[0] = sum_exp;
    }
    __syncthreads();
    sum_exp = shared_sum[0];

    // Normalize by dividing by sum
    float inv_sum = 1.0f / (sum_exp + 1e-7f);  // Small epsilon for numerical stability
    for (int i = tid; i < dim; i += blockDim.x) {
        out_ptr[i] *= inv_sum;
    }
}

torch::Tensor softmax_hip(torch::Tensor x) {
    TORCH_CHECK(x.dim() == 2, "Input must be 2D tensor");
    int batch_size = x.size(0);
    int dim = x.size(1);

    auto out = torch::empty_like(x);

    int block_size = 256;  // 4 warps
    int num_blocks = batch_size;

    hipLaunchKernelGGL(
        softmax_kernel,
        dim3(num_blocks), dim3(block_size), 0, 0,
        x.data_ptr<float>(), out.data_ptr<float>(), batch_size, dim
    );

    return out;
}
"""

softmax = load_inline(
    name="softmax_optimized",
    cpp_sources=softmax_hip_source,
    functions=["softmax_hip"],
    verbose=True,
    with_cuda=True,
    extra_cflags=["-O3"],
)

class ModelNew(nn.Module):
    """
    Optimized model with custom HIP softmax kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
