depthwise_conv_cpp_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

#define TILE_SIZE 16
#define KERNEL_SIZE 3
#define BLOCK_SIZE 256

__global__ void depthwise_conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int height,
    int width,
    int kernel_size,
    int stride,
    int padding,
    int out_height,
    int out_width
) {
    int batch = blockIdx.z;
    int channel = blockIdx.y;

    // Calculate output position for this thread
    int total_out_pixels = out_height * out_width;
    int tid = blockIdx.x * blockDim.x + threadIdx.x;

    if (batch >= batch_size || channel >= in_channels || tid >= total_out_pixels) {
        return;
    }

    int out_h = tid / out_width;
    int out_w = tid % out_width;

    // Calculate input position
    int in_h_start = out_h * stride - padding;
    int in_w_start = out_w * stride - padding;

    float sum = 0.0f;

    // Convolution
    for (int kh = 0; kh < kernel_size; kh++) {
        int in_h = in_h_start + kh;
        if (in_h >= 0 && in_h < height) {
            int h_offset = in_h * width;
            for (int kw = 0; kw < kernel_size; kw++) {
                int in_w = in_w_start + kw;
                if (in_w >= 0 && in_w < width) {
                    // Input index: (batch, channel, h, w)
                    int input_idx = ((batch * in_channels + channel) * height + in_h) * width + in_w;
                    // Weight index: (channel, kh, kw) but since it's depthwise, we use channel for output_channel too
                    int weight_idx = channel * kernel_size * kernel_size + kh * kernel_size + kw;

                    sum += input[input_idx] * weight[weight_idx];
                }
            }
        }
    }

    // Output index: (batch, channel, out_h, out_w)
    int output_idx = ((batch * in_channels + channel) * out_height + out_h) * out_width + out_w;
    output[output_idx] = sum;
}

__global__ void depthwise_conv2d_tiled_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int height,
    int width,
    int kernel_size,
    int stride,
    int padding,
    int out_height,
    int out_width
) {
    extern __shared__ float shared_input[];

    int batch = blockIdx.z;
    int channel = blockIdx.y;

    // Tile dimensions
    int tile_out_h = TILE_SIZE;
    int tile_out_w = TILE_SIZE;

    // Calculate output position
    int tile_start_h = blockIdx.x * tile_out_h;
    int tile_start_w = 0; // Only tile along height for simplicity

    int out_h_base = tile_start_h;

    // Load input tile to shared memory
    int in_h_start = out_h_base * stride - padding;
    // Pad the input tile
    int tile_h = tile_out_h * stride + kernel_size - 1;

    int tx = threadIdx.x;

    // Load tile
    for (int i = tx; i < tile_h * width; i += blockDim.x) {
        int local_h = i / width;
        int local_w = i % width;
        int global_h = in_h_start + local_h;

        if (global_h >= 0 && global_h < height) {
            int input_idx = ((batch * in_channels + channel) * height + global_h) * width + local_w;
            shared_input[i] = input[input_idx];
        } else {
            shared_input[i] = 0.0f;
        }
    }

    __syncthreads();

    // Compute output
    for (int out_h_local = 0; out_h_local < tile_out_h; out_h_local++) {
        int out_h = out_h_base + out_h_local;
        if (out_h < out_height) {
            // Each thread computes multiple output positions in width
            for (int out_w_local = tx; out_w_local < out_width; out_w_local += blockDim.x) {
                int out_w = out_w_local;

                float sum = 0.0f;

                for (int kh = 0; kh < kernel_size; kh++) {
                    int shared_h = out_h_local * stride + kh;
                    if (shared_h >= 0 && shared_h < tile_h) {
                        for (int kw = 0; kw < kernel_size; kw++) {
                            int in_w_local = out_w * stride - padding + kw;
                            if (in_w_local >= 0 && in_w_local < width) {
                                int shared_idx = shared_h * width + in_w_local;
                                int weight_idx = channel * kernel_size * kernel_size + kh * kernel_size + kw;
                                sum += shared_input[shared_idx] * weight[weight_idx];
                            }
                        }
                    }
                }

                int output_idx = ((batch * in_channels + channel) * out_height + out_h) * out_width + out_w;
                output[output_idx] = sum;
            }
        }
    }
}

torch::Tensor depthwise_conv2d_hip(torch::Tensor input, torch::Tensor weight, int stride, int padding) {
    auto batch_size = input.size(0);
    auto in_channels = input.size(1);
    auto height = input.size(2);
    auto width = input.size(3);
    auto kernel_size = weight.size(2);

    auto out_height = (height + 2 * padding - kernel_size) / stride + 1;
    auto out_width = (width + 2 * padding - kernel_size) / stride + 1;

    auto output = torch::zeros({batch_size, in_channels, out_height, out_width}, input.options());

    int total_out_pixels = out_height * out_width;

    // Heuristic: use simple kernel for small outputs, tiled for larger ones
    bool use_tiled = (total_out_pixels > 4096);

    if (use_tiled) {
        // Tiled version for larger outputs
        int tile_size = TILE_SIZE;
        int num_tiles_h = (out_height + tile_size - 1) / tile_size;
        int tile_h = tile_size * stride + kernel_size - 1;
        int shared_mem_size = tile_h * width * sizeof(float);

        dim3 blockDim(256);
        dim3 gridDim(num_tiles_h, in_channels, batch_size);

        depthwise_conv2d_tiled_kernel<<<gridDim, blockDim, shared_mem_size>>>(
            input.data_ptr<float>(),
            weight.data_ptr<float>(),
            output.data_ptr<float>(),
            batch_size,
            in_channels,
            height,
            width,
            kernel_size,
            stride,
            padding,
            out_height,
            out_width
        );
    } else {
        // Simple version for smaller outputs
        dim3 blockDim(BLOCK_SIZE);
        int total_threads = (total_out_pixels + BLOCK_SIZE - 1) / BLOCK_SIZE;
        dim3 gridDim(total_threads, in_channels, batch_size);

        depthwise_conv2d_kernel<<<gridDim, blockDim>>>(
            input.data_ptr<float>(),
            weight.data_ptr<float>(),
            output.data_ptr<float>(),
            batch_size,
            in_channels,
            height,
            width,
            kernel_size,
            stride,
            padding,
            out_height,
            out_width
        );
    }

    return output;
}
