bmm_hip_source = """
#include <hip/hip_runtime.h>

#define TILE_M 64
#define TILE_N 64
#define TILE_K 16
#define WARP_SIZE 32

__global__ void batched_matmul_kernel(
    const float* A, const float* B, float* C,
    int batch_size, int M, int K, int N
) {
    int batch = blockIdx.z;

    // Calculate global row and column in output matrix
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    // Boundary check
    if (row >= M || col >= N) return;

    // Accumulator
    float sum = 0.0f;

    // Loop over K dimension with tiling
    for (int t = 0; t < K; t += TILE_K) {
        // Compute partial sum for this tile
        #pragma unroll
        for (int k = 0; k < TILE_K && (t + k) < K; k++) {
            float a_val = A[batch * M * K + row * K + (t + k)];
            float b_val = B[batch * K * N + (t + k) * N + col];
            sum += a_val * b_val;
        }
    }

    // Write result
    C[batch * M * N + row * N + col] = sum;
}

__global__ void batched_matmul_tiled_kernel(
    const float* A, const float* B, float* C,
    int batch_size, int M, int K, int N
) {
    // Thread and block indices
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int batch = blockIdx.z;

    // Calculate global position
    int row = by * TILE_M + ty;
    int col = bx * TILE_N + tx;

    // Shared memory for tiles (with padding to avoid bank conflicts)
    __shared__ float As[TILE_M][TILE_K + 1];  // +1 for padding
    __shared__ float Bs[TILE_K][TILE_N + 1];  // +1 for padding

    // Accumulator
    float sum = 0.0f;

    // Loop over tiles in K dimension
    for (int t = 0; t < K; t += TILE_K) {
        // Load tile of A - each thread loads one element
        int a_row = by * TILE_M + ty;
        int a_col = t + tx;
        if (a_row < M && a_col < K) {
            As[ty][tx] = A[batch * M * K + a_row * K + a_col];
        } else {
            As[ty][tx] = 0.0f;
        }

        // Load tile of B
        int b_row = t + ty;
        int b_col = bx * TILE_N + tx;
        if (b_row < K && b_col < N) {
            Bs[ty][tx] = B[batch * K * N + b_row * N + b_col];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        // Synchronize to ensure tiles are loaded
        __syncthreads();

        // Compute partial sum for this tile
        #pragma unroll
        for (int k = 0; k < TILE_K; k++) {
            sum += As[ty][k] * Bs[k][tx];
        }

        // Synchronize before loading next tile
        __syncthreads();
    }

    // Write result
    if (row < M && col < N) {
        C[batch * M * N + row * N + col] = sum;
    }
}

torch::Tensor batched_bmm_hip(torch::Tensor A, torch::Tensor B) {
    int batch_size = A.size(0);
    int M = A.size(1);
    int K = A.size(2);
    int N = B.size(2);

    auto C = torch::zeros_like(A);
    C = C.view({batch_size, M, N}).clone();

    // Choose thread block size
    dim3 blockDim(TILE_N, TILE_M);
    dim3 gridDim((N + TILE_N - 1) / TILE_N, (M + TILE_M - 1) / TILE_M, batch_size);

    batched_matmul_tiled_kernel<<<gridDim, blockDim>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        batch_size, M, K, N
    );

    return C;
}
"""

