rmsnorm_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void rmsnorm_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    const int batch_size,
    const int features,
    const int dim1,
    const int dim2,
    const float eps) {

    // Grid layout: blockIdx.x = d1, blockIdx.y = d2, blockIdx.z = batch
    // Thread index processes feature dimension
    int b = blockIdx.z;
    int d1 = blockIdx.x;
    int d2 = blockIdx.y;
    int f = threadIdx.x;

    // Shared memory for reduction
    __shared__ float shared_sums[256];

    // Compute sum of squares for this feature
    float sum_sq = 0.0f;
    if (f < features) {
        int idx = ((b * features + f) * dim1 + d1) * dim2 + d2;
        float val = x[idx];
        sum_sq = val * val;
    }

    shared_sums[f] = sum_sq;

    // Synchronize all threads in the block
    __syncthreads();

    // Parallel reduction in shared memory
    for (int stride = 128; stride > 0; stride >>= 1) {
        if (f < stride) {
            shared_sums[f] += shared_sums[f + stride];
        }
        __syncthreads();
    }

    // Thread 0 computes the RMS and stores back to shared memory
    if (f == 0) {
        shared_sums[0] = sqrtf(shared_sums[0] / features + eps);
    }
    __syncthreads();

    // Divide by RMS
    if (f < features) {
        int idx = ((b * features + f) * dim1 + d1) * dim2 + d2;
        out[idx] = x[idx] / shared_sums[0];
    }
}

torch::Tensor rmsnorm_hip(torch::Tensor x, int num_features, float eps) {
    auto batch_size = x.size(0);
    auto features = x.size(1);
    auto dim1 = x.size(2);
    auto dim2 = x.size(3);

    auto out = torch::zeros_like(x);

    // Use threads for feature dimension
    const int block_size = 256;
    dim3 block_dims(block_size);

    // Grid for (dim1, dim2, batch)
    dim3 grid_dims(dim1, dim2, batch_size);

    rmsnorm_kernel<<<grid_dims, block_dims>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size,
        features,
        dim1,
        dim2,
        eps
    );

    return out;
}
