matmul_cpp_source = """
#include <hip/hip_runtime.h>

#define TILE_SIZE 32
#define TBM 16  // Each thread computes TBM×TBN output elements
#define TBN 16

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Thread block dimensions: (TBN, TBM) = (16, 16)
    // Each block computes a (TBM*TILE_SIZE) x (TBN*TILE_SIZE) = 512 x 512 output region
    int by = blockIdx.y;
    int bx = blockIdx.x;

    // Starting row and column for this block's output
    int row_block_start = by * TBM * TILE_SIZE;
    int col_block_start = bx * TBN * TILE_SIZE;

    // Each thread computes a TILE_SIZE x TILE_SIZE (32x32) output region
    // Row and column within the block
    int thread_row_offset = threadIdx.y * TILE_SIZE;
    int thread_col_offset = threadIdx.x * TILE_SIZE;

    int row0 = row_block_start + thread_row_offset;
    int col0 = col_block_start + thread_col_offset;

    // Shared memory for tiles - add padding to avoid bank conflicts
    __shared__ float As[TBM * TILE_SIZE][TILE_SIZE + 1];
    __shared__ float Bs[TILE_SIZE + 1][TBN * TILE_SIZE];

    // Each thread computes TILE_SIZE x TILE_SIZE = 1024 output elements
    float sum[TILE_SIZE][TILE_SIZE];

    // Initialize sums
    #pragma unroll
    for (int i = 0; i < TILE_SIZE; ++i) {
        #pragma unroll
        for (int j = 0; j < TILE_SIZE; ++j) {
            sum[i][j] = 0.0f;
        }
    }

    // Loop over tiles
    int num_tiles = (N + TILE_SIZE - 1) / TILE_SIZE;
    for (int t = 0; t < num_tiles; ++t) {
        // Load tiles into shared memory
        // Each thread loads TILE_SIZE elements from each matrix

        int k_start = t * TILE_SIZE;  // Starting column of A tile, starting row of B tile

        // Load tile of A: shape (TBM*TILE_SIZE) x TILE_SIZE
        // Thread (tx, ty) loads rows [ty*TILE_SIZE:(ty+1)*TILE_SIZE] and column range of the tile
        #pragma unroll
        for (int i = 0; i < TILE_SIZE; ++i) {
            int row = thread_row_offset + i;
            int col = k_start + threadIdx.x;

            if (row < N && col < N) {
                As[row][threadIdx.x] = A[row * N + col];
            } else {
                As[row][threadIdx.x] = 0.0f;
            }
        }

        // Load tile of B: shape TILE_SIZE x (TBN*TILE_SIZE)
        // Thread (tx, ty) loads row of the tile and columns [tx*TILE_SIZE:(tx+1)*TILE_SIZE]
        #pragma unroll
        for (int i = 0; i < TILE_SIZE; ++i) {
            int row = k_start + threadIdx.y;
            int col = thread_col_offset + i;

            if (row < N && col < N) {
                Bs[threadIdx.y][i] = B[row * N + col];
            } else {
                Bs[threadIdx.y][i] = 0.0f;
            }
        }

        __syncthreads();

        // Compute partial sums
        #pragma unroll
        for (int k = 0; k < TILE_SIZE; ++k) {
            #pragma unroll
            for (int i = 0; i < TILE_SIZE; ++i) {
                #pragma unroll
                for (int j = 0; j < TILE_SIZE; ++j) {
                    sum[i][j] += As[thread_row_offset + i][k] * Bs[k][thread_col_offset + j];
                }
            }
        }

        __syncthreads();
    }

    // Store results to global memory
    #pragma unroll
    for (int i = 0; i < TILE_SIZE; ++i) {
        int row = row0 + i;
        if (row < N) {
            #pragma unroll
            for (int j = 0; j < TILE_SIZE; ++j) {
                int col = col0 + j;
                if (col < N) {
                    C[row * N + col] = sum[i][j];
                }
            }
        }
    }
}

torch::Tensor matmul_hip(torch::Tensor A, torch::Tensor B) {
    auto N = A.size(0);
