    dim3 blockDim(TBN, TBM);

    // Grid dimensions
    int output_tiles_per_dim = (N + TBM * TILE_SIZE - 1) / (TBM * TILE_SIZE);
    dim3 gridDim(output_tiles_per_dim, output_tiles_per_dim);

    matmul_kernel<<<gridDim, blockDim, 0, at::cuda::getCurrentCUDAStream()>>>(
        A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
