conv2d_cpp_source = """
#include <hip/hip_runtime.h>

#define TILE_SIZE 8

__global__ void conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    const int batch_size,
    const int in_channels,
    const int out_channels,
    const int height_in,
    const int width_in,
    const int height_out,
    const int width_out,
    const int kernel_size,
    const int stride,
    const int padding,
    const int dilation) {

    // Calculate output dimensions
    const int out_size = batch_size * out_channels * height_out * width_out;
    const int idx = blockIdx.x * TILE_SIZE * TILE_SIZE + threadIdx.x;

    if (idx >= out_size) return;

    // Decode output position
    const int b = idx / (out_channels * height_out * width_out);
    const int remaining = idx % (out_channels * height_out * width_out);
    const int oc = remaining / (height_out * width_out);
    const int spatial_idx = remaining % (height_out * width_out);
    const int h_out = spatial_idx / width_out;
    const int w_out = spatial_idx % width_out;

    // Calculate corresponding input positions
    const int h_in_start = h_out * stride - padding;
    const int w_in_start = w_out * stride - padding;

    // Accumulator
    float sum = 0.0f;

    // Unroll the 3x3 kernel loop for performance
    for (int ic = 0; ic < in_channels; ++ic) {
        // Determine base indices for this channel
        const int input_base = ((b * in_channels + ic) * height_in + h_in_start) * width_in + w_in_start;
        const int weight_base = (oc * in_channels + ic) * kernel_size * kernel_size;

        // Manual unrolling of 3x3 kernel
        // Row 0
        bool valid00 = (h_in_start >= 0 && h_in_start < height_in && w_in_start >= 0 && w_in_start < width_in);
        bool valid01 = (h_in_start >= 0 && h_in_start < height_in && w_in_start + dilation >= 0 && w_in_start + dilation < width_in);
        bool valid02 = (h_in_start >= 0 && h_in_start < height_in && w_in_start + 2*dilation >= 0 && w_in_start + 2*dilation < width_in);

        // Row 1
        bool valid10 = (h_in_start + dilation >= 0 && h_in_start + dilation < height_in && w_in_start >= 0 && w_in_start < width_in);
        bool valid11 = (h_in_start + dilation >= 0 && h_in_start + dilation < height_in && w_in_start + dilation >= 0 && w_in_start + dilation < width_in);
        bool valid12 = (h_in_start + dilation >= 0 && h_in_start + dilation < height_in && w_in_start + 2*dilation >= 0 && w_in_start + 2*dilation < width_in);

        // Row 2
        bool valid20 = (h_in_start + 2*dilation >= 0 && h_in_start + 2*dilation < height_in && w_in_start >= 0 && w_in_start < width_in);
        bool valid21 = (h_in_start + 2*dilation >= 0 && h_in_start + 2*dilation < height_in && w_in_start + dilation >= 0 && w_in_start + dilation < width_in);
        bool valid22 = (h_in_start + 2*dilation >= 0 && h_in_start + 2*dilation < height_in && w_in_start + 2*dilation >= 0 && w_in_start + 2*dilation < width_in);

        if (valid00 && valid01 && valid02 && valid10 && valid11 && valid12 && valid20 && valid21 && valid22) {
            // All positions valid - fast path
            sum += input[input_base] * weight[weight_base];
            sum += input[input_base + dilation] * weight[weight_base + 1];
            sum += input[input_base + 2*dilation] * weight[weight_base + 2];
            sum += input[input_base + dilation*width_in] * weight[weight_base + 3];
            sum += input[input_base + dilation*width_in + dilation] * weight[weight_base + 4];
            sum += input[input_base + dilation*width_in + 2*dilation] * weight[weight_base + 5];
            sum += input[input_base + 2*dilation*width_in] * weight[weight_base + 6];
            sum += input[input_base + 2*dilation*width_in + dilation] * weight[weight_base + 7];
            sum += input[input_base + 2*dilation*width_in + 2*dilation] * weight[weight_base + 8];
        } else {
            // Check each position individually with boundary handling
            for (int kh = 0; kh < kernel_size; ++kh) {
                for (int kw = 0; kw < kernel_size; ++kw) {
                    const int h_in = h_out * stride - padding + kh * dilation;
                    const int w_in = w_out * stride - padding + kw * dilation;

                    if (h_in >= 0 && h_in < height_in && w_in >= 0 && w_in < width_in) {
                        const float in_val = input[((b * in_channels + ic) * height_in + h_in) * width_in + w_in];
                        const float w_val = weight[(oc * in_channels + ic) * kernel_size * kernel_size + kh * kernel_size + kw];
                        sum += in_val * w_val;
                    }
                }
            }
        }
    }

    output[idx] = sum;
}

