sum_reduction_cpp_source = """
#include <hip/hip_runtime.h>

#define WARP_SIZE 64
#define MAX_BLOCK_SIZE 1024

__device__ __forceinline__ float warp_reduce_sum(float val) {
    for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
        val += __shfl_down(val, offset);
    }
    return val;
}

__global__ void sum_reduction_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch_size,
    int reduce_dim,
    int other_dim
) {
    int batch_idx = blockIdx.x;
    int other_idx = blockIdx.y * blockDim.x + threadIdx.x;

    if (batch_idx >= batch_size || other_idx >= other_dim) {
        return;
    }

    float sum = 0.0f;

    // Each thread processes the entire reduction dimension
    const float* input_ptr = input + batch_idx * reduce_dim * other_dim + other_idx;

    // Loop over reduction dimension with stride to avoid bank conflicts
    for (int i = 0; i < reduce_dim; i++) {
        sum += input_ptr[i * other_dim];
    }

    // Store result
    output[batch_idx * other_dim + other_idx] = sum;
}

__global__ void sum_reduction_tiled_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch_size,
    int reduce_dim,
    int other_dim
) {
    extern __shared__ float sdata[];
    int batch_idx = blockIdx.x;
    int other_idx = blockIdx.y;

    if (batch_idx >= batch_size || other_idx >= other_dim) {
        return;
    }

    int tid = threadIdx.x;

    // Load data into shared memory with coalesced access
    const float* input_ptr = input + batch_idx * reduce_dim * other_dim + other_idx;

    float sum = 0.0f;
    for (int i = tid; i < reduce_dim; i += blockDim.x) {
        sum += input_ptr[i * other_dim];
    }

    sdata[tid] = sum;
    __syncthreads();

    // Reduction in shared memory
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    // Write result
    if (tid == 0) {
        output[batch_idx * other_dim + other_idx] = sdata[0];
    }
}

torch::Tensor sum_reduction_hip(torch::Tensor x, int dim) {
    TORCH_CHECK(x.dim() == 3, "Input tensor must be 3-dimensional");

    auto batch_size = x.size(0);
    auto dim1 = x.size(1);
    auto dim2 = x.size(2);

    auto output = torch::zeros({batch_size, 1, dim2}, x.options());

    int reduce_dim_size = dim1;
    int other_dim_size = dim2;

    // Choose kernel based on reduction dimension size
    if (reduce_dim_size < 512) {
        // For small reduction dimensions, use simple parallel kernel
        int threads_per_block = 256;
        int blocks_x = batch_size;
        int blocks_y = (other_dim_size + threads_per_block - 1) / threads_per_block;

        dim3 grid(blocks_x, blocks_y);
        dim3 block(threads_per_block);

        sum_reduction_kernel<<<grid, block>>>(
            x.data_ptr<float>(),
            output.data_ptr<float>(),
            batch_size,
            reduce_dim_size,
            other_dim_size
        );
    } else {
        // For larger reduction dimensions, use shared memory tiled reduction
        int block_size = 256;
        dim3 grid(batch_size, other_dim_size);
        dim3 block(block_size);

        sum_reduction_tiled_kernel<<<grid, block, block_size * sizeof(float)>>>(
            x.data_ptr<float>(),
            output.data_ptr<float>(),
            batch_size,
            reduce_dim_size,
            other_dim_size
        );
    }

    return output;
}
"""

