#include <hip/hip_runtime.h>

#define TILE_SIZE 256
#define TILE_NUM_ROWS 8

__global__ void matvec_mul_kernel(const float* A, const float* B, float* C, int M, int K) {
    __shared__ float As[TILE_NUM_ROWS][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE];

    int block_row = blockIdx.x * TILE_NUM_ROWS;
    int thread_idx = threadIdx.x;

    float partial_sum = 0.0f;

    // Process tiles
    for (int tile_start = 0; tile_start < K; tile_start += TILE_SIZE) {
        // Load B tile (synchronous across threads)
        #pragma unroll
        for (int j = 0; j < (TILE_SIZE + 255) / 256; j++) {
            int idx = thread_idx + j * 256;
            if (idx < TILE_SIZE && (tile_start + idx) < K) {
                Bs[idx] = B[tile_start + idx];
            }
        }
        __syncthreads();

        // Each thread computes one element of its assigned row
        int row_local = thread_idx / (TILE_SIZE / TILE_NUM_ROWS);
        int col_local = thread_idx % (TILE_SIZE / TILE_NUM_ROWS);
        int row = block_row + row_local;

        if (row < M && row_local < TILE_NUM_ROWS) {
            // Load A tile elements for this row
            float a_val[4];
            int base_col = tile_start + col_local * 4;

            #pragma unroll
            for (int i = 0; i < 4; i++) {
                if (base_col + i < K && base_col + i < tile_start + TILE_SIZE) {
                    a_val[i] = A[row * K + base_col + i];
                } else {
                    a_val[i] = 0.0f;
                }
            }

            #pragma unroll
            for (int i = 0; i < 4; i++) {
                int b_idx = base_col + i - tile_start;
                if (b_idx >= 0 && b_idx < TILE_SIZE) {
                    partial_sum += a_val[i] * Bs[b_idx];
                }
            }
        }
        __syncthreads();
    }

    // Reduce partial sums across threads for the same row
    if (thread_idx < TILE_NUM_ROWS && (block_row + thread_idx) < M) {
        extern __shared__ float temp[];
        temp[thread_idx] = 0.0f;

        int row = block_row + thread_idx;

        // Gather partial sums from all threads for this row
        for (int t = 0; t < TILE_SIZE / TILE_NUM_ROWS; t++) {
            int src_thread = thread_idx * (TILE_SIZE / TILE_NUM_ROWS) + t;
            if (src_thread < TILE_SIZE) {
                temp[thread_idx] += partial_sum;
            }
        }

        C[row] = temp[thread_idx];
    }
}

