    int thread_col = threadIdx.x;

    // Global row and column indices
    int row = row_block * blockDim.y + thread_row;
    int col = col_block * blockDim.x + thread_col;

    // Check bounds
    if (row >= M || col >= N) return;

    // Compute dot product for this output element
    float sum = 0.0f;

    // Iterate over K dimension (the small shared dimension)
    for (int k = 0; k < K; k++) {
        float a_val = A[row * K + k];
        float b_val = B[k * N + col];
        sum += a_val * b_val;
    }

    // Store result
    C[row * N + col] = sum;
}

