    // Use 16x16 thread blocks for good occupancy
    const int BLOCK_ROWS = 16;
    const int BLOCK_COLS = 16;

    dim3 blockDim(BLOCK_COLS, BLOCK_ROWS);
    dim3 gridDim((N + BLOCK_COLS - 1) / BLOCK_COLS, (M + BLOCK_ROWS - 1) / BLOCK_ROWS);

    tall_skinny_matmul_kernel<<<gridDim, blockDim>>>(
        A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(),
        M, K, N);

    return C;
}
