layernorm_cpp_source = """
#include <hip/hip_runtime.h>
#include <math.h>

// Warp-level reduction helper
__device__ __forceinline__ float warp_reduce_sum(float val) {
    #if __HIP_ARCH_WAVEFRONT_SIZE == 32
        for (int mask = 16; mask > 0; mask /= 2) {
            val += __shfl_down_f32(val, mask);
        }
    #elif __HIP_ARCH_WAVEFRONT_SIZE == 64
        for (int mask = 32; mask > 0; mask /= 2) {
            val += __shfl_down_f32(val, mask);
        }
    #endif
    return val;
}

__global__ void layernorm_kernel(
    const float* __restrict__ x,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ out,
    int batch_size,
    int features,
    int dim1,
    int dim2,
    int N) {

    int b = blockIdx.x;
    int f = blockIdx.y;
    int idx = b * features + f;

    // Position of this normalization's data in input
    const float* x_ptr = x + idx * N;
    float* out_ptr = out + idx * N;

    // Use shared memory for loading and reduction
    extern __shared__ float shared_data[];

    float local_sum = 0.0f;
    float local_sum_sq = 0.0f;

    // Process N elements per normalization, using multiple warps
    int num_warps = blockDim.x / 64;  // Assuming 64 threads per warp on AMD
    int lane_id = threadIdx.x % 64;
    int warp_id = threadIdx.x / 64;

    // Each warp processes a portion of the data
    int elements_per_warp = (N + num_warps - 1) / num_warps;
    int start = warp_id * elements_per_warp;
    int end = min(start + elements_per_warp, N);

    for (int i = start + lane_id; i < end; i += 64) {
        float val = x_ptr[i];
        local_sum += val;
        local_sum_sq += val * val;
    }

    // Warp reduction to sum
    local_sum = warp_reduce_sum(local_sum);
    local_sum_sq = warp_reduce_sum(local_sum_sq);

    // Store results in shared memory
    __shared__ float warp_sums[128];
    __shared__ float warp_sum_sqs[128];

    if (lane_id == 0 && warp_id < 128) {
        warp_sums[warp_id] = local_sum;
        warp_sum_sqs[warp_id] = local_sum_sq;
    }
    __syncthreads();

    // Final reduction across warps
    float total_sum = 0.0f;
    float total_sum_sq = 0.0f;

    if (threadIdx.x < num_warps && threadIdx.x < 128) {
        total_sum += warp_sums[threadIdx.x];
        total_sum_sq += warp_sum_sqs[threadIdx.x];
    }

    __shared__ float mean_val;
    __shared__ float var_val;

    // Compute mean and variance
    if (threadIdx.x == 0) {
        mean_val = total_sum / (float)N;
        float mean_sq = mean_val * mean_val;
        float mean_of_squares = total_sum_sq / (float)N;
        var_val = mean_of_squares - mean_sq;
        var_val = fmaxf(var_val, 0.0f);  // Ensure non-negative
    }
    __syncthreads();

    // Apply normalization: out = gamma * (x - mean) / sqrt(var + eps) + beta
    float gamma_val = gamma[f];
    float beta_val = beta[f];
    float inv_std = rsqrtf(var_val + 1e-5f);  // LayerNorm epsilon

    for (int i = start + lane_id; i < end; i += 64) {
        float val = x_ptr[i];
        float norm_val = (val - mean_val) * inv_std;
        out_ptr[i] = gamma_val * norm_val + beta_val;
    }
}

torch::Tensor layernorm_hip(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta) {
    auto batch_size = x.size(0);
    auto features = x.size(1);
    auto dim1 = x.size(2);
    auto dim2 = x.size(3);
    auto N = dim1 * dim2;

    auto out = torch::zeros_like(x);

    int num_warps = (N + 63) / 64;  // Number of warps needed per normalization
    int threads = min(num_warps * 64, 1024);  // Cap at 1024 threads

    dim3 grid(batch_size, features);
    dim3 block(threads);
    size_t shared_mem = 2 * 128 * sizeof(float);  // For warp sums

    layernorm_kernel<<<grid, block, shared_mem>>>(
        x.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size,
        features,
        dim1,
        dim2,
        N
    );

    return out;
}
"""

