cross_entropy_cpp_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

#define BLOCK_SIZE 128
#define WARP_SIZE 32

__device__ float warp_reduce_max(float val) {
    val = max(val, __shfl_down(val, 16));
    val = max(val, __shfl_down(val, 8));
    val = max(val, __shfl_down(val, 4));
    val = max(val, __shfl_down(val, 2));
    val = max(val, __shfl_down(val, 1));
    return val;
}

__device__ float warp_reduce_sum(float val) {
    val += __shfl_down(val, 16);
    val += __shfl_down(val, 8);
    val += __shfl_down(val, 4);
    val += __shfl_down(val, 2);
    val += __shfl_down(val, 1);
    return val;
}

__global__ void cross_entropy_loss_kernel(
    const float* predictions,
    const int64_t* targets,
    float* loss,
    int batch_size,
    int num_classes
) {
    int batch_idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (batch_idx >= batch_size) {
        return;
    }

    int lane_id = threadIdx.x % WARP_SIZE;
    int warp_id = threadIdx.x / WARP_SIZE;
    int num_warps = blockDim.x / WARP_SIZE;

    int sample_idx = blockIdx.x * blockDim.x + warp_id * WARP_SIZE + lane_id;

    if (sample_idx >= batch_size) {
        if (lane_id == 0) {
            loss[blockIdx.x * num_warps + warp_id] = 0.0f;
        }
        return;
    }

    const float* preds = predictions + sample_idx * num_classes;
    int target_idx = targets[sample_idx];
    float target_pred = preds[target_idx];

    // Vectorized load with float4 for efficiency
    const float4* preds_vec = (const float4*)preds;

    // Compute max
    float max_val = -INFINITY;
    for (int c = threadIdx.x; c < num_classes / 4; c += blockDim.x) {
        float4 v = preds_vec[c];
        max_val = fmaxf(max_val, v.x);
        max_val = fmaxf(max_val, v.y);
        max_val = fmaxf(max_val, v.z);
        max_val = fmaxf(max_val, v.w);
    }
    // Handle remaining elements
    int start = (num_classes / 4) * 4;
    for (int c = start + threadIdx.x; c < num_classes; c += blockDim.x) {
        max_val = fmaxf(max_val, preds[c]);
    }

    // Warp reduction for max
    max_val = warp_reduce_max(max_val);

    // Compute sum of exp with vectorized loads
    float sum_exp = 0.0f;
    for (int c = threadIdx.x; c < num_classes / 4; c += blockDim.x) {
        float4 v = preds_vec[c];
        sum_exp += expf(v.x - max_val);
        sum_exp += expf(v.y - max_val);
        sum_exp += expf(v.z - max_val);
        sum_exp += expf(v.w - max_val);
    }
    // Handle remaining elements
    for (int c = start + threadIdx.x; c < num_classes; c += blockDim.x) {
        sum_exp += expf(preds[c] - max_val);
    }

    // Warp reduction for sum
    sum_exp = warp_reduce_sum(sum_exp);

    // Compute cross entropy loss for this sample
    float sample_loss = -target_pred + max_val + logf(sum_exp);

    // Store result
    if (lane_id == 0) {
        loss[blockIdx.x * num_warps + warp_id] = sample_loss;
    }
}

__global__ void sum_loss_kernel(
    const float* sample_losses,
    float* total_loss,
    int num_samples
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    extern __shared__ float sdata[];
    sdata[threadIdx.x] = (idx < num_samples) ? sample_losses[idx] : 0.0f;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            sdata[threadIdx.x] += sdata[threadIdx.x + s];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        atomicAdd(total_loss, sdata[0] / (float)num_samples);
    }
}

torch::Tensor cross_entropy_hip(torch::Tensor predictions, torch::Tensor targets) {
    int batch_size = predictions.size(0);
    int num_classes = predictions.size(1);

    // Use one thread per sample, with each block processing multiple samples
    const int block_size = 128;
    const int numblocks = (batch_size + block_size - 1) / block_size;

    auto sample_losses = torch::zeros({numblocks * 4}, predictions.options());

    // Launch kernel
    cross_entropy_loss_kernel<<<numblocks, block_size>>>(
        predictions.data_ptr<float>(),
        targets.data_ptr<int64_t>(),
        sample_losses.data_ptr<float>(),
        batch_size,
        num_classes
    );

    // Compute mean loss
    auto mean_loss = torch::zeros({1}, predictions.options());

    // Actually only batch_size entries are valid
    int num_valid_losses = batch_size;
    int reduce_blocks = (num_valid_losses + block_size - 1) / block_size;
    sum_loss_kernel<<<reduce_blocks, block_size, block_size * sizeof(float)>>>(
        sample_losses.data_ptr<float>(),
        mean_loss.data_ptr<float>(),
        num_valid_losses
    );

    return mean_loss;
}
"""

cross_entropy_module = load_inline(
    name="cross_entropy_loss",
    cpp_sources=cross_entropy_cpp_source,
    functions=["cross_entropy_hip"],
    verbose=True,
)


