rmsnorm_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void rmsnorm_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    const int batch_size,
    const int features,
    const int dim1,
    const int dim2,
    const float eps) {

    // Let each thread process multiple coordinates to increase computational intensity
    // Total coordinates = batch_size * dim1 * dim2
    int64_t total_coords = (int64_t)batch_size * dim1 * dim2;

    // Use 256 threads per block
    const int block_size = 256;

    // Each thread processes 64 coordinates
    const int coords_per_thread = 64;

    int64_t my_coord_start = (int64_t)blockIdx.x * block_size * coords_per_thread + threadIdx.x * coords_per_thread;

    for (int coord_offset = 0; coord_offset < coords_per_thread; ++coord_offset) {
        int64_t global_coord = my_coord_start + coord_offset;

        if (global_coord < total_coords) {
            // Convert linear coordinate back to (batch, d1, d2)
            int b = global_coord / (dim1 * dim2);
            int remaining = global_coord % (dim1 * dim2);
            int d1 = remaining / dim2;
            int d2 = remaining % dim2;

            // Compute reduction
            float sum_sq = 0.0f;
            for (int f = 0; f < features; ++f) {
                int idx = ((b * features + f) * dim1 + d1) * dim2 + d2;
                float val = x[idx];
                sum_sq += val * val;
            }

            // Compute RMS (mean has 1/features term, sqrt applied, then div by RMS has 1/sqrt(sqrt(sum/f + eps)))
            float mean_sq = sum_sq / features;
            float rms = sqrtf(mean_sq + eps);

            // Divide all 64 features by the computed RMS
            for (int f = 0; f < features; ++f) {
                int idx = ((b * features + f) * dim1 + d1) * dim2 + d2;
                out[idx] = x[idx] / rms;
            }
        }
    }
}

torch::Tensor rmsnorm_hip(torch::Tensor x, int num_features, float eps) {
    auto batch_size = x.size(0);
    auto features = x.size(1);
    auto dim1 = x.size(2);
    auto dim2 = x.size(3);

    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int coords_per_thread = 64;
    int64_t total_coords = (int64_t)batch_size * dim1 * dim2;
    int64_t total_threads = (total_coords + coords_per_thread - 1) / coords_per_thread;
    int num_blocks = (total_threads + block_size - 1) / block_size;

    rmsnorm_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size,
        features,
        dim1,
        dim2,
        eps
    );

    return out;
