matmul_hip_source = """
#include <hip/hip_runtime.h>

#define TILE_M 64
#define TILE_N 64
#define TILE_K 16

__global__ void matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M, int K, int N
) {
    // Thread indices
    int tx = threadIdx.x;  // 0..TILE_N-1
    int ty = threadIdx.y;  // 0..TILE_M-1

    // Block position
    int bx = blockIdx.x;   // blockIdx.x in x-direction
    int by = blockIdx.y;   // blockIdx.y in y-direction

    // Global row and column
    int global_row = by * TILE_M + ty;
    int global_col = bx * TILE_N + tx;

    // Allocate shared memory for tiles
    __shared__ float As[TILE_M][TILE_K];
    __shared__ float Bs[TILE_K][TILE_N];

    // Accumulator registers
    float c[TILE_N] = {0.0f};
    #pragma unroll
    for (int i = 0; i < TILE_N; i++) {
        c[i] = 0.0f;
    }

    // Compute this tile
    for (int tk = 0; tk < (K + TILE_K - 1) / TILE_K; tk++) {
        // Load A tile
        #pragma unroll
        for (int i = 0; i < TILE_M / 16; i++) {
            int row = global_row;
            int col = tk * TILE_K + tx;

            if (row + i * 16 < M && col < K) {
                As[ty + i * 16][tx] = A[(row + i * 16) * K + col];
            } else {
                As[ty + i * 16][tx] = 0.0f;
            }
        }

        // Load B tile
        #pragma unroll
        for (int i = 0; i < TILE_N / 16; i++) {
            int row = tk * TILE_K + ty;
            int col = global_col + i * 16;

            if (row < K && col + i * 16 < N) {
                Bs[ty][tx + i * 16] = B[row * N + col + i * 16];
            } else {
                Bs[ty][tx + i * 16] = 0.0f;
            }
        }

        __syncthreads();

        // Compute
        #pragma unroll
        for (int k = 0; k < TILE_K; k++) {
            #pragma unroll
            for (int i = 0; i < TILE_N / 16; i++) {
                #pragma unroll
                for (int j = 0; j < 16; j++) {
                    c[i * 16 + j] += As[ty][k] * Bs[k][tx + i * 16 + j];
                }
            }
        }

        __syncthreads();
    }

    // Store results
    #pragma unroll
    for (int i = 0; i < TILE_N / 16; i++) {
        #pragma unroll
        for (int j = 0; j < 16; j++) {
            int row = global_row;
            int col = global_col + i * 16 + j;

            if (row < M && col < N) {
                C[row * N + col] = c[i * 16 + j];
            }
        }
    }
}

torch::Tensor matmul_hip(torch::Tensor A, torch::Tensor B) {
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    auto C = torch::zeros({M, N}, A.options());

    dim3 blockDim(TILE_N, TILE_M / 16);
    dim3 gridDim((N + TILE_N - 1) / TILE_N, (M + TILE_M - 1) / TILE_M);

    matmul_kernel<<<gridDim, blockDim>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, K, N);

    return C;
}
