#include <hip/hip_runtime.h>
#include <math.h>

template<typename T>
__global__ void maxpool2d_kernel_shared(
    const T* __restrict__ input,
    T* __restrict__ output,
    const int batch_size,
    const int channels,
    const int input_height,
    const int input_width,
    const int output_height,
    const int output_width,
    const int kernel_size,
    const int stride,
    const int padding,
    const int dilation
) {
    // Each thread block processes a tile of output
    // TILE_SIZE x TILE_SIZE output elements per block
    // We need to load a larger input tile to account for kernel size and padding
    const int TILE_SIZE = 16;
    const int INPUT_TILE_SIZE = TILE_SIZE + (kernel_size - 1) * dilation + 2 * padding;

    __shared__ T input_tile[INPUT_TILE_SIZE][INPUT_TILE_SIZE];

    // Global output coordinates
    int output_x = blockIdx.x * TILE_SIZE + threadIdx.x;
    int output_y = blockIdx.y * TILE_SIZE + threadIdx.y;
    int b = blockIdx.z / channels;
    int c = blockIdx.z % channels;

    if (b >= batch_size) return;

    // Each thread loads one element from input to shared memory
    // The input tile starts at the top-left of our output region minus padding
    int input_start_x_global = blockIdx.x * TILE_SIZE * stride - padding;
    int input_start_y_global = blockIdx.y * TILE_SIZE * stride - padding;

    int load_x_relative = threadIdx.x;
    int load_y_relative = threadIdx.y;
    int input_x_global = input_start_x_global + load_x_relative;
    int input_y_global = input_start_y_global + load_y_relative;

    // Load multiple elements per thread (vectorized loading)
    for (int i = 0; i < INPUT_TILE_SIZE; i += TILE_SIZE) {
        for (int j = 0; j < INPUT_TILE_SIZE; j += TILE_SIZE) {
            int lx = load_x_relative + j;
            int ly = load_y_relative + i;
            int ix = input_x_global + j;
            int iy = input_y_global + i;

            if (lx < INPUT_TILE_SIZE && ly < INPUT_TILE_SIZE) {
                if (ix >= 0 && ix < input_width && iy >= 0 && iy < input_height) {
                    int input_idx = b * channels * input_height * input_width 
                                  + c * input_height * input_width 
                                  + iy * input_width 
                                  + ix;
                    input_tile[ly][lx] = input[input_idx];
                } else {
                    input_tile[ly][lx] = -INFINITY;
                }
            }
        }
    }

    __syncthreads();

    // Process the output elements for this thread
    if (output_x < output_width && output_y < output_height) {
        T max_val = -INFINITY;

        // Calculate input region in shared memory
        int input_start_x_local = threadIdx.x * stride - padding;
        int input_start_y_local = threadIdx.y * stride - padding;

        #pragma unroll
        for (int ky = 0; ky < kernel_size; ++ky) {
            int input_y_local = input_start_y_local + ky * dilation;
            if (input_y_local < 0 || input_y_local >= INPUT_TILE_SIZE) continue;

            #pragma unroll
            for (int kx = 0; kx < kernel_size; ++kx) {
                int input_x_local = input_start_x_local + kx * dilation;
                if (input_x_local < 0 || input_x_local >= INPUT_TILE_SIZE) continue;

                T val = input_tile[input_y_local][input_x_local];
                if (val > max_val) {
                    max_val = val;
                }
            }
        }

        int output_idx = b * channels * output_height * output_width 
                       + c * output_height * output_width 
                       + output_y * output_width 
                       + output_x;
        output[output_idx] = max_val;
    }
}

template<typename T>
__global__ void maxpool2d_kernel_vectorized(
    const T* __restrict__ input,
    T* __restrict__ output,
    const int batch_size,
    const int channels,
    const int input_height,
    const int input_width,
    const int output_height,
    const int output_width,
    const int kernel_size,
    const int stride,
    const int padding,
    const int dilation
) {
    const int VECTOR_SIZE = 4;  // Vectorize 4 elements at a time

    // Each thread processes multiple output elements in the channel dimension
    int output_x = blockIdx.x * blockDim.x + threadIdx.x;
    int output_z = blockIdx.y * blockDim.y + threadIdx.y;  // Combined (batch, channel)

    if (output_x >= output_width || output_z >= batch_size * channels) {
        return;
    }

    int b = output_z / channels;
    int c = output_z % channels;

    // Vectorized output processing
    T vals[VECTOR_SIZE];
    #pragma unroll
    for (int v = 0; v < VECTOR_SIZE; v++) {
        vals[v] = -INFINITY;
    }

    // Calculate input coordinates
    int input_start_x = output_x * stride - padding;

    // Precompute input stride for contiguous memory access
    int batch_channel_offset = b * channels * input_height * input_width + c * input_height * input_width;

    // Iterate over pooling window
    #pragma unroll
    for (int ky = 0; ky < kernel_size; ++ky) {
        int input_y = (blockIdx.z * blockDim.z + threadIdx.z) * stride;  // Use blockIdx.z for Y dimension
        int y_start = input_y + ky * dilation - padding;
        if (y_start < 0 || y_start >= input_height) continue;

        int row_offset = batch_channel_offset + y_start * input_width;

        #pragma unroll
        for (int kx = 0; kx < kernel_size; ++kx) {
            int input_x = input_start_x + kx * dilation;
            if (input_x >= 0 && input_x < input_width) {
                int input_idx = row_offset + input_x;
                T val = input[input_idx];
                T* target = vals;
                if (val > *target) *target = val;
            }
        }
    }

    // Write outputs
    int output_width_pitch = output_width;
    #pragma unroll
    for (int v = 0; v < VECTOR_SIZE; v++) {
        int out_z = output_z + v;
        if (out_z < batch_size * channels) {
            int out_x = output_x;
            int out_y = blockIdx.z * blockDim.z + threadIdx.z;
            if (out_y < output_height) {
                int output_idx = (out_z / channels) * channels * output_height * output_width 
                               + (out_z % channels) * output_height * output_width 
                               + out_y * output_width 
                               + out_x;
                output[output_idx] = vals[v];
            }
        }
    }
}

torch::Tensor maxpool2d_hip(torch::Tensor input, int kernel_size, int stride, int padding, int dilation) {
    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto input_height = input.size(2);
    auto input_width = input.size(3);

    // Calculate output dimensions
    int output_height = (input_height + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int output_width = (input_width + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;

    auto output = torch::zeros({batch_size, channels, output_height, output_width}, input.options());

    const int BLOCK_SIZE = 16;

    dim3 block(BLOCK_SIZE, BLOCK_SIZE);

    // Calculate grid dimensions
    int grid_x = (output_width + BLOCK_SIZE - 1) / BLOCK_SIZE;
    int grid_y = (output_height + BLOCK_SIZE - 1) / BLOCK_SIZE;
    int grid_z = batch_size * channels;

    dim3 grid(grid_x, grid_y, grid_z);

    maxpool2d_kernel_vectorized<float><<<grid, block>>>(
