#include <hip/hip_runtime.h>

__global__ void rmsnorm_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    const int batch_size,
    const int features,
    const int dim1,
    const int dim2,
    const float eps) {

    // Linear coordinate index
    int64_t coord_idx = blockIdx.x;

    // Decode to (batch, d1, d2)
    int b = coord_idx / (dim1 * dim2);
    int remaining = coord_idx % (dim1 * dim2);
    int d1_coord = remaining / dim2;
    int d2_coord = remaining % dim2;

    // Each thread processes multiple features for better arithmetic intensity
    int tid = threadIdx.x;
    const int feats_per_thread = 2; // Each thread handles 2 features
    int my_num_feats = feats_per_thread;
    if (tid * feats_per_thread >= features) {
        my_num_feats = 0;
    } else if ((tid + 1) * feats_per_thread > features) {
        my_num_feats = features - tid * feats_per_thread;
    }

    // Shared memory for parallel reduction and load/store buffers
    __shared__ float s_sum[256];  // For reduction
    __shared__ float s_rms[1];    // RMS value for all threads

    // Compute sum of squares for features assigned to this thread
    float local_sum = 0.0f;
    #pragma unroll
    for (int i = 0; i < feats_per_thread; ++i) {
        int f = tid * feats_per_thread + i;
        if (f < features) {
            // Use strided access - not consecutive but consistent
            int idx = ((b * features + f) * dim1 + d1_coord) * dim2 + d2_coord;
            float val = x[idx];
            local_sum += val * val;
        }
    }

    s_sum[tid] = local_sum;
    __syncthreads();

    // Parallel reduction in shared memory
    #pragma unroll
    for (int stride = 128; stride > 0; stride >>= 1) {
        if (tid < stride) {
            s_sum[tid] += s_sum[tid + stride];
        }
        __syncthreads();
    }

    // Only thread 0 computes RMS
    if (tid == 0) {
        float mean_sq = s_sum[0] / features;
        s_rms[0] = sqrtf(mean_sq + eps);
    }
    __syncthreads();

    float rms = s_rms[0];

    // Divide all features (same thread assignments as before)
    #pragma unroll
    for (int i = 0; i < feats_per_thread; ++i) {
        int f = tid * feats_per_thread + i;
        if (f < features) {
            int idx = ((b * features + f) * dim1 + d1_coord) * dim2 + d2_coord;
            out[idx] = x[idx] / rms;
        }
    }
}

