#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

#define BLOCK_SIZE 256
#define WARP_SIZE 32

__device__ float warp_reduce_max(float val) {
    val = max(val, __shfl_down(val, 16));
    val = max(val, __shfl_down(val, 8));
    val = max(val, __shfl_down(val, 4));
    val = max(val, __shfl_down(val, 2));
    val = max(val, __shfl_down(val, 1));
    return val;
}

__device__ float warp_reduce_sum(float val) {
    val += __shfl_down(val, 16);
    val += __shfl_down(val, 8);
    val += __shfl_down(val, 4);
    val += __shfl_down(val, 2);
    val += __shfl_down(val, 1);
    return val;
}

__global__ void cross_entropy_kernel(
    const float* predictions,
    const int64_t* targets,
    float* losses,
    int batch_size,
    int num_classes
) {
    int batch_idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (batch_idx >= batch_size) {
        return;
    }

    const float* preds = predictions + batch_idx * num_classes;
    int target_idx = targets[batch_idx];
    float target_pred = preds[target_idx];
    int lane_id = threadIdx.x % WARP_SIZE;

    // Compute max for numerical stability
    float max_val = -INFINITY;
    for (int c = lane_id; c < num_classes; c += WARP_SIZE) {
        max_val = fmaxf(max_val, preds[c]);
    }

    max_val = warp_reduce_max(max_val);

    // Compute sum of exp
    float sum_exp = 0.0f;
    for (int c = lane_id; c < num_classes; c += WARP_SIZE) {
        sum_exp += expf(preds[c] - max_val);
    }

    sum_exp = warp_reduce_sum(sum_exp);

    // Compute cross entropy loss for this sample
    float sample_loss = -target_pred + max_val + logf(sum_exp);

    // Store result
    if (lane_id == 0) {
        int warp_idx = (blockIdx.x * blockDim.x + threadIdx.x) / WARP_SIZE;
        losses[warp_idx] = sample_loss;
    }
}

torch::Tensor cross_entropy_hip(torch::Tensor predictions, torch::Tensor targets) {
    int batch_size = predictions.size(0);
    int num_classes = predictions.size(1);

    const int block_size = BLOCK_SIZE;
    const int num_blocks = (batch_size + block_size - 1) / block_size;

    // Compute per-sample losses
    auto sample_losses = torch::zeros({num_blocks * 8}, predictions.options());

    cross_entropy_kernel<<<num_blocks, block_size>>>(
        predictions.data_ptr<float>(),
        targets.data_ptr<int64_t>(),
        sample_losses.data_ptr<float>(),
        batch_size,
        num_classes
    );

    // Compute mean loss
    auto mean_loss = sample_losses [:batch_size].mean();

    return mean_loss;
}
