rmsnorm_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void rmsnorm_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    const int batch_size,
    const int features,
    const int dim1,
    const int dim2,
    const float eps) {

    // Each warp processes one (batch, d1, d2) coordinate
    // Total coordinates: batch_size * dim1 * dim2
    // Each coordinate needs to reduce over features=64

    int64_t coord_idx = blockIdx.x * blockDim.y + threadIdx.y;
    int64_t total_coords = (int64_t)batch_size * dim1 * dim2;

    if (coord_idx >= total_coords) return;

    // Compute (batch, d1, d2) from linear index
    int tmp = coord_idx;
    int d2 = tmp % dim2;
    tmp /= dim2;
    int d1 = tmp % dim1;
    int batch = tmp / dim1;

    // Base offset for this coordinate
    int64_t base_offset = batch * (int64_t)dim1 * dim2 * features;

    // Reduce over features using warp-level primitives
    int tid = threadIdx.x;
    int lane_id = tid % 32;

    float sum_sq = 0.0f;

    // Each thread in warp processes some features (features=64 is small)
    // For better occupancy, assign features per thread evenly
    int feat_start = tid;
    int feat_stride = blockDim.x;

    for (int f = feat_start; f < features; f += feat_stride) {
        int64_t idx = base_offset + f * dim1 * dim2 + d1 * dim2 + d2;
        float val = x[idx];
        sum_sq += val * val;
    }

    // Warp reduction
    #pragma unroll
    for (int offset = 16; offset > 0; offset /= 2) {
        sum_sq += __shfl_down(sum_sq, offset);
    }

    // Lane 0 has the final sum
    sum_sq = __shfl(sum_sq, 0);

    // Compute RMS
    float mean_sq = sum_sq / features;
    float rms = sqrtf(mean_sq + eps);

    // Write output - same pattern as before
    for (int f = feat_start; f < features; f += feat_stride) {
        int64_t idx = base_offset + f * dim1 * dim2 + d1 * dim2 + d2;
        out[idx] = x[idx] / rms;
    }
}

torch::Tensor rmsnorm_hip(torch::Tensor x, int num_features, float eps) {
    auto batch_size = x.size(0);
    auto features = x.size(1);
    auto dim1 = x.size(2);
    auto dim2 = x.size(3);

    auto out = torch::zeros_like(x);

    int64_t total_coords = (int64_t)batch_size * dim1 * dim2;

    // Config: use 32 threads per warp (warps work together on reduction)
    // Each block can have multiple warps
    dim3 block(32, 8); // 32 threads per warp, 8 warps per block = 256 threads
    int warps_per_block = block.y;
    int coords_per_block = warps_per_block;

    int num_blocks = (total_coords + coords_per_block - 1) / coords_per_block;

    rmsnorm_kernel<<<num_blocks, block>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size,
        features,
        dim1,
        dim2,
        eps
    );

    return out;
}
"""

rmsnorm_module = load_inline(
    name="rmsnorm_module",
    cpp_sources=rmsnorm_cpp_source,
    functions=["rmsnorm_hip"],
    verbose=True,
)


class ModelNew(nn.Module):
    """
