#include <hip/hip_runtime.h>
#include <math.h>

__global__ void gelu_kernel(const float* x, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Process 4 elements per thread for better memory coalescing
    #pragma unroll
    for (int i = 0; i < 4; i++) {
        int actual_idx = idx * 4 + i;
        if (actual_idx < size) {
            float xi = x[actual_idx];
            // GELU approximation: 0.5 * x * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
            float x3 = xi * xi * xi;
            float arg = 0.7978845608028654f * (xi + 0.044715f * x3);  // sqrt(2/pi) ≈ 0.7978845608028654
            float tanh_val = tanhf(arg);
            out[actual_idx] = 0.5f * xi * (1.0f + tanh_val);
        }
    }
}

torch::Tensor gelu_hip(torch::Tensor x) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + 4 * block_size - 1) / (4 * block_size);

    gelu_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
