#include <hip/hip_runtime.h>

#define TILE_SIZE 256

__global__ void matvec_mul_kernel(const float* A, const float* B, float* C, int M, int K) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;

    if (row >= M) return;

    __shared__ float B_shared[TILE_SIZE];

    float sum = 0.0f;

    // Process B in tiles
    for (int tile_start = 0; tile_start < K; tile_start += TILE_SIZE) {
        // Each thread in the block loads one element of B into shared memory
        int idx = threadIdx.x;
        if (tile_start + idx < K) {
            B_shared[idx] = B[tile_start + idx];
        } else {
            B_shared[idx] = 0.0f;
        }
        __syncthreads();

        // Compute partial dot product for this tile
        int tile_end = min(tile_start + TILE_SIZE, K);
        #pragma unroll 4
        for (int j = tile_start; j < tile_end; j++) {
            // Calculate which shared memory slot this j maps to
            int shared_idx = j - tile_start;
            sum += A[row * K + j] * B_shared[shared_idx];
        }
        __syncthreads();
    }

    C[row] = sum;
}

