layernorm_cpp_source = """
#include <hip/hip_runtime.h>
#include <math.h>

__global__ void layernorm_kernel(
    const float* __restrict__ x,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ out,
    int batch_size,
    int features,
    int dim1,
    int dim2,
    int N) {

    int b = blockIdx.x;
    int f = blockIdx.y;
    int idx = b * features + f;

    // Position of this normalization's data in input
    const float* x_ptr = x + idx * N;
    float* out_ptr = out + idx * N;

    // Use shared memory for reductions
    extern __shared__ float shared_data[];

    float local_sum = 0.0f;
    float local_sum_sq = 0.0f;

    // Each thread processes multiple elements to cover N = dim1 * dim2
    int tid = threadIdx.x;
    int stride = blockDim.x;

    for (int i = tid; i < N; i += stride) {
        float val = x_ptr[i];
        local_sum += val;
        local_sum_sq += val * val;
    }

    // Reduction in shared memory
    shared_data[tid] = local_sum;
    shared_data[tid + blockDim.x] = local_sum_sq;
    __syncthreads();

    // Parallel reduction
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_data[tid] += shared_data[tid + s];
            shared_data[tid + blockDim.x] += shared_data[tid + blockDim.x + s];
        }
        __syncthreads();
    }

    // Compute mean and variance
    float total_sum = shared_data[0];
    float total_sum_sq = shared_data[blockDim.x];
    float mean_val = total_sum / (float)N;
    float var_val = (total_sum_sq / (float)N) - (mean_val * mean_val);
    var_val = fmaxf(var_val, 0.0f);  // Ensure non-negative

    // Apply normalization: out = gamma * (x - mean) / sqrt(var + eps) + beta
    float gamma_val = gamma[f];
    float beta_val = beta[f];
    float inv_std = rsqrtf(var_val + 1e-5f);  // LayerNorm epsilon

    for (int i = tid; i < N; i += stride) {
        float val = x_ptr[i];
        float norm_val = (val - mean_val) * inv_std;
        out_ptr[i] = gamma_val * norm_val + beta_val;
    }
}

torch::Tensor layernorm_hip(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta) {
    auto batch_size = x.size(0);
    auto features = x.size(1);
    auto dim1 = x.size(2);
    auto dim2 = x.size(3);
    auto N = dim1 * dim2;

    auto out = torch::zeros_like(x);

    int threads = 256;

    dim3 grid(batch_size, features);
    dim3 block(threads);

    // 2 * threads for storing sum and sum_sq
    layernorm_kernel<<<grid, block, 2 * threads * sizeof(float)>>>(
        x.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size,
        features,
        dim1,
        dim2,
        N
    );

    return out;
}
"""

