softmax_hip_source = """
#include <hip/hip_runtime.h>

#define WARP_SIZE 64

__device__ __forceinline__ float warp_reduce_max(float val) {
    #pragma unroll
    for (int offset = 32; offset > 0; offset /= 2) {
        val = fmaxf(val, __shfl_down(val, offset));
    }
    return val;
}

__device__ __forceinline__ float warp_reduce_sum(float val) {
    #pragma unroll
    for (int offset = 32; offset > 0; offset /= 2) {
        val += __shfl_down(val, offset);
    }
    return val;
}

__global__ void softmax_kernel(const float* __restrict__ x, float* __restrict__ out, int batch_size, int dim) {
    int row = blockIdx.x;
    if (row >= batch_size) return;

    const float* row_ptr = x + row * dim;
    float* out_ptr = out + row * dim;

    int tid = threadIdx.x;
    int lane_id = tid % WARP_SIZE;
    int warp_id = tid / WARP_SIZE;
    int warps_per_block = (blockDim.x + WARP_SIZE - 1) / WARP_SIZE;

    // Shared memory for inter-warp reduction (32 elements max)
    __shared__ float smem[32];

    // Phase 1: Find maximum (for numerical stability)
    float local_max = -INFINITY;
    for (int i = tid; i < dim; i += blockDim.x) {
        local_max = fmaxf(local_max, row_ptr[i]);
    }
    // Warp-level reduction
    local_max = warp_reduce_max(local_max);
    // Broadcast max to all threads and reduce across warps
    if (lane_id == 0) smem[warp_id] = local_max;
    __syncthreads();
    if (warp_id == 0 && lane_id < 32) {
        local_max = smem[lane_id];
        local_max = warp_reduce_max(local_max);
        if (lane_id == 0) smem[0] = local_max;
    }
    __syncthreads();
    float max_val = smem[0];

    // Phase 2: Compute exp sum
    float local_sum = 0.0f;
    for (int i = tid; i < dim; i += blockDim.x) {
        float val = expf(row_ptr[i] - max_val);
        local_sum += val;
        out_ptr[i] = val;  // Store exp values for now
    }
    // Warp-level reduction
    local_sum = warp_reduce_sum(local_sum);
    // Reduce sum across warps
    if (lane_id == 0) smem[warp_id] = local_sum;
    __syncthreads();
    if (warp_id == 0 && lane_id < 32) {
        local_sum = smem[lane_id];
        local_sum = warp_reduce_sum(local_sum);
        if (lane_id == 0) smem[0] = local_sum;
    }
    __syncthreads();
    float sum_exp = smem[0] + 1e-7f;  // Add epsilon for numerical stability

    // Phase 3: Normalize
    float inv_sum = 1.0f / sum_exp;
    for (int i = tid; i < dim; i += blockDim.x) {
        out_ptr[i] *= inv_sum;
    }
}

torch::Tensor softmax_hip(torch::Tensor x) {
    TORCH_CHECK(x.dim() == 2, "Input must be 2D tensor");
    int batch_size = x.size(0);
    int dim = x.size(1);

    auto out = torch::empty_like(x);

    int block_size = 256;  // 4 warps, good balance
    int num_blocks = batch_size;

    hipLaunchKernelGGL(
        softmax_kernel,
        dim3(num_blocks), dim3(block_size), 0, 0,
        x.data_ptr<float>(), out.data_ptr<float>(), batch_size, dim
    );

    return out;
}
