sum_reduction_cpp_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

#define BLOCK_SIZE 256

__global__ void sum_reduction_optimized_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch_size,
    int reduce_dim,
    int other_dim
) {
    // Each thread block handles one (batch, other) pair
    int batch_idx = blockIdx.x;
    int other_idx = blockIdx.y;

    if (batch_idx >= batch_size || other_idx >= other_dim) {
        return;
    }

    __shared__ float s_data[BLOCK_SIZE];

    int tid = threadIdx.x;
    int reduce_size = reduce_dim;

    // Get base pointer for this (batch, other) pair
    const float* base_ptr = input + batch_idx * reduce_dim * other_dim + other_idx;

    // Each thread processes multiple elements
    float sum = 0.0f;

    // Accumulate elements for this thread
    for (int i = tid; i < reduce_size; i += BLOCK_SIZE) {
        sum += base_ptr[i * other_dim];
    }

    // Store in shared memory
    s_data[tid] = sum;
    __syncthreads();

    // Reduction in shared memory
    // Use a more efficient reduction tree
    if (BLOCK_SIZE >= 512) { if (tid < 256) { s_data[tid] += s_data[tid + 256]; } __syncthreads(); }
    if (BLOCK_SIZE >= 256) { if (tid < 128) { s_data[tid] += s_data[tid + 128]; } __syncthreads(); }
    if (BLOCK_SIZE >= 128) { if (tid < 64)  { s_data[tid] += s_data[tid + 64]; }  __syncthreads(); }

    // Warp-level reduction (no sync needed for warp)
    if (tid < 32) {
        float val = s_data[tid];
        val += __shfl_down(val, 16);
        val += __shfl_down(val, 8);
        val += __shfl_down(val, 4);
        val += __shfl_down(val, 2);
        val += __shfl_down(val, 1);
        s_data[tid] = val;
    }

    // Write result
    if (tid == 0) {
        output[batch_idx * other_dim + other_idx] = s_data[0];
    }
}

__global__ void sum_reduction_multi_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch_size,
    int reduce_dim,
    int other_dim
) {
    extern __shared__ float s_data[];

    int batch_idx = blockIdx.x;

    if (batch_idx >= batch_size) {
        return;
    }

    int tid = threadIdx.x;

    // Each block handles multiple (other_dim) elements
    int elements_per_block = (other_dim + blockDim.y - 1) / blockDim.y;
    int block_y = blockIdx.y;

    int other_start = block_y * elements_per_block;
    int other_end = min(other_start + elements_per_block, other_dim);

    const float* batch_input = input + batch_idx * reduce_dim * other_dim;
    float* batch_output = output + batch_idx * other_dim;

    for (int other_idx = other_start; other_idx < other_end; other_idx++) {
        // Accumulate for this other_idx
        float sum = 0.0f;
        for (int i = tid; i < reduce_dim; i += blockDim.x) {
            sum += batch_input[i * other_dim + other_idx];
        }

        s_data[tid] = sum;
        __syncthreads();

        // Reduction
        for (int s = blockDim.x / 2; s > 0; s >>= 1) {
            if (tid < s) {
                s_data[tid] += s_data[tid + s];
            }
            __syncthreads();
        }

        if (tid == 0) {
            batch_output[other_idx] = s_data[0];
        }
    }
}

torch::Tensor sum_reduction_hip(torch::Tensor x, int dim) {
    TORCH_CHECK(x.dim() == 3, "Input tensor must be 3-dimensional");

    auto batch_size = x.size(0);
    auto dim1 = x.size(1);
    auto dim2 = x.size(2);

    auto output = torch::zeros({batch_size, 1, dim2}, x.options());

    int reduce_dim_size = dim1;
    int other_dim_size = dim2;

    // Use optimized kernel with each block handling one (batch, other) pair
    int block_size = BLOCK_SIZE;
    dim3 grid(batch_size, other_dim_size);
    dim3 block(block_size);

    sum_reduction_optimized_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        reduce_dim_size,
        other_dim_size
    );

    return output;
}
