    const int width_in = input.size(3);
    const int out_channels = weight.size(0);
    const int kernel_size = weight.size(2);

    const int height_out = (height_in + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    const int width_out = (width_in + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;

    const int out_size = batch_size * out_channels * height_out * width_out;

    auto output = torch::zeros({batch_size, out_channels, height_out, width_out}, input.options());

    const int threads_per_block = TILE_SIZE * TILE_SIZE;
    const int num_blocks = (out_size + threads_per_block - 1) / threads_per_block;

    hipLaunchKernelGGL(
        conv2d_kernel,
        dim3(num_blocks),
        dim3(threads_per_block),
        0,
        0,
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        height_in,
        width_in,
        height_out,
