softmax_hip_source = """
#include <hip/hip_runtime.h>

#define WARP_SIZE 64
#define VEC_SIZE 4  // Load 4 elements at a time

__device__ __forceinline__ float warp_reduce_max(float val) {
    #pragma unroll
    for (int offset = 32; offset > 0; offset /= 2) {
        val = fmaxf(val, __shfl_down(val, offset));
    }
    return val;
}

__device__ __forceinline__ float warp_reduce_sum(float val) {
    #pragma unroll
    for (int offset = 32; offset > 0; offset /= 2) {
        val += __shfl_down(val, offset);
    }
    return val;
}

__global__ void softmax_kernel(const float* __restrict__ x, float* __restrict__ out, int batch_size, int dim) {
    int row = blockIdx.y;
    if (row >= batch_size) return;

    const float* row_ptr = x + row * dim;
    float* out_ptr = out + row * dim;

    int block_idx = blockIdx.x;
    int num_blocks_for_row = gridDim.x;
    int tid = threadIdx.x;

    // Partition the work across blocks
    int segment_size = (dim + num_blocks_for_row - 1) / num_blocks_for_row;
    int start = block_idx * segment_size;
    int end = min(start + segment_size, dim);
    int len = end - start;

    if (start >= dim) return;

    int lane_id = tid % WARP_SIZE;
    int warp_id = tid / WARP_SIZE;

    // Shared memory for inter-block communication
    __shared__ float smem[32];

    // Process in vectorized chunks
    const float* ptr = row_ptr + start;

    // Compute local max
    float local_max = -INFINITY;

    // Scalar elements at start (for alignment)
    int vec_start = (start + VEC_SIZE - 1) & ~(VEC_SIZE - 1);
    int scalar_end = min(vec_start, end);

    for (int i = tid; i < (scalar_end - start); i += blockDim.x) {
        local_max = fmaxf(local_max, ptr[i]);
    }

    // Vectorized loads
    int vec_elements = (end - vec_start) / VEC_SIZE;
    ptr += vec_start - start;

    for (int i = tid; i < vec_elements; i += blockDim.x) {
        float4 v = reinterpret_cast<const float4*>(ptr)[i];
        local_max = fmaxf(local_max, fmaxf(fmaxf(v.x, v.y), fmaxf(v.z, v.w)));
    }

    // Warp reduction
    local_max = warp_reduce_max(local_max);

    // Cross-warp reduction within block
    if (lane_id == 0) smem[warp_id] = local_max;
    __syncthreads();
    if (warp_id == 0 && lane_id < 32) {
        local_max = smem[lane_id];
        local_max = warp_reduce_max(local_max);
        if (lane_id == 0) smem[0] = local_max;
    }
    __syncthreads();
    float block_max = smem[0];

    // Compute local exp sum using vectorized loads
    float local_sum = 0.0f;

    // Scalar phase
    for (int i = tid; i < (scalar_end - start); i += blockDim.x) {
        float val = expf(ptr[i] - block_max);
        local_sum += val;
        out_ptr[start + i] = val;
    }

    // Vectorized phase
    for (int i = tid; i < vec_elements; i += blockDim.x) {
        float4 v = reinterpret_cast<const float4*>(ptr)[i];
        float4 out_val;
        out_val.x = expf(v.x - block_max);
        out_val.y = expf(v.y - block_max);
        out_val.z = expf(v.z - block_max);
        out_val.w = expf(v.w - block_max);
        local_sum += out_val.x + out_val.y + out_val.z + out_val.w;
        reinterpret_cast<float4*>(out_ptr + vec_start)[i] = out_val;
    }

    // Warp reduction
    local_sum = warp_reduce_sum(local_sum);

    // Cross-warp reduction
    if (lane_id == 0) smem[warp_id] = local_sum;
    __syncthreads();
    if (warp_id == 0 && lane_id < 32) {
        local_sum = smem[lane_id];
        local_sum = warp_reduce_sum(local_sum);
        if (lane_id == 0) smem[0] = local_sum;
    }
    __syncthreads();
    float block_sum = smem[0];

    // Normalize - scalar phase
    float inv_sum = 1.0f / (block_sum + 1e-7f);
    for (int i = tid; i < (scalar_end - start); i += blockDim.x) {
        out_ptr[start + i] *= inv_sum;
    }

    // Normalize - vectorized phase
    for (int i = tid; i < vec_elements; i += blockDim.x) {
        float4 v = reinterpret_cast<float4*>(out_ptr + vec_start)[i];
        v.x *= inv_sum;
        v.y *= inv_sum;
        v.z *= inv_sum;
        v.w *= inv_sum;
        reinterpret_cast<float4*>(out_ptr + vec_start)[i] = v;
    }
}

torch::Tensor softmax_hip(torch::Tensor x) {
    TORCH_CHECK(x.dim() == 2, "Input must be 2D tensor");
    int batch_size = x.size(0);
    int dim = x.size(1);

    auto out = torch::empty_like(x);

    const int block_size = 256;
    // Use multiple blocks per row for large dimensions
    int blocks_per_row = min(32, (dim + 65535) / 65536);  // Tune based on dimension
    dim3 grid(blocks_per_row, batch_size);

    hipLaunchKernelGGL(
        softmax_kernel,
        grid, dim3(block_size), 0, 0,
        x.data_ptr<float>(), out.data_ptr<float>(), batch_size, dim
    );

    return out;
}
