    auto M = A.size(0);
    auto K = A.size(1);
    auto C = torch::zeros({M, 1}, A.options());

    dim3 block(THREADS_PER_ROW);
    dim3 grid(M);

    matvec_mul_kernel<<<grid, block>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, K);

    return C;
}
