matmul_hip_source = """
#include <hip/hip_runtime.h>

#define TILE_SIZE 16

__global__ void matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M, int K, int N
) {
    // Block index
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Thread index
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Index of the first element of A processed by the thread block
    int aBegin = by * TILE_SIZE * K;
    int aEnd = aBegin + K;
    int aStep = TILE_SIZE;

    // Index of the first element of B processed by the thread block
    int bBegin = TILE_SIZE * bx;
    int bStep = TILE_SIZE * N;

    // C element computed by this thread
    float c = 0.0f;

    // Loop over all tiles
    for (int a = aBegin, b = bBegin; a < aEnd; a += aStep, b += bStep) {
        // Shared memory for A and B tiles
        __shared__ float As[TILE_SIZE][TILE_SIZE];
        __shared__ float Bs[TILE_SIZE][TILE_SIZE];

        // Load tiles into shared memory
        // Each thread loads one element
        int global_row_a = by * TILE_SIZE + ty;
        int global_col_a = a + tx;

        int global_row_b = b / N + ty;
        int global_col_b = b + tx;

        // Load A tile
        if (global_row_a < M && global_col_a < aEnd && global_col_a < aBegin + K) {
            As[ty][tx] = A[global_col_a + global_row_a * K];
        } else {
            As[ty][tx] = 0.0f;
        }

        // Load B tile
        if (global_row_b < K && global_col_b < bBegin + TILE_SIZE * N && global_col_b < N) {
            int b_col = (b % N) + tx;
            int b_row = (b / N) + ty;
            if (b_row < K && b_col < N) {
                Bs[ty][tx] = B[b_row * N + b_col];
            } else {
                Bs[ty][tx] = 0.0f;
            }
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial result
        #pragma unroll
        for (int k = 0; k < TILE_SIZE; ++k) {
            c += As[ty][k] * Bs[k][tx];
        }

        __syncthreads();
    }

    // Write result to global memory
    int global_row = by * TILE_SIZE + ty;
    int global_col = bx * TILE_SIZE + tx;

    if (global_row < M && global_col < N) {
        C[global_row * N + global_col] = c;
    }
}

torch::Tensor matmul_hip(torch::Tensor A, torch::Tensor B) {
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    auto C = torch::zeros({M, N}, A.options());

    dim3 blockDim(TILE_SIZE, TILE_SIZE);
    dim3 gridDim((N + TILE_SIZE - 1) / TILE_SIZE, (M + TILE_SIZE - 1) / TILE_SIZE);

    matmul_kernel<<<gridDim, blockDim>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, K, N);

    return C;
}
"""

