#include <hip/hip_runtime.h>

#define TILE_M 32
#define TILE_N 32
#define TILE_K 16

__global__ void batched_matmul_tiled_kernel(
    const float* A, const float* B, float* C,
    int batch_size, int M, int K, int N
) {
    // Thread and block indices
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int batch = blockIdx.z;

    // Calculate global position
    int row = by * TILE_M + ty;
    int col = bx * TILE_N + tx;

    // Shared memory for tiles (with padding to avoid bank conflicts)
    __shared__ float As[TILE_M][TILE_K + 1];  // +1 for padding
    __shared__ float Bs[TILE_K][TILE_N + 1];  // +1 for padding

    // Accumulator
    float sum = 0.0f;

    // Loop over tiles in K dimension
    for (int t = 0; t < K; t += TILE_K) {
        // Load tile of A - each thread loads one element
        int a_row = by * TILE_M + ty;
        int a_col = t + tx;
        if (a_row < M && a_col < K) {
            As[ty][tx] = A[batch * M * K + a_row * K + a_col];
        } else {
            As[ty][tx] = 0.0f;
        }

        // Load tile of B
        int b_row = t + ty;
        int b_col = bx * TILE_N + tx;
        if (b_row < K && b_col < N) {
            Bs[ty][tx] = B[batch * K * N + b_row * N + b_col];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        // Synchronize to ensure tiles are loaded
        __syncthreads();

        // Compute partial sum for this tile
        #pragma unroll
        for (int k = 0; k < TILE_K; k++) {
            sum += As[ty][k] * Bs[k][tx];
        }

        // Synchronize before loading next tile
        __syncthreads();
    }

    // Write result
    if (row < M && col < N) {
        C[batch * M * N + row * N + col] = sum;
    }
}

