#include <hip/hip_runtime.h>

__global__ void tall_skinny_matmul_kernel_vectorized(
    const float* A, const float* B, float* C,
    int M, int K, int N) {

    // Each thread computes 4 output elements for better utilization
    const int ELEMENTS_PER_THREAD = 4;

    // Block indices
    int by = blockIdx.y;
    int bx = blockIdx.x;

    // Thread index
    int tx = threadIdx.x;

    // Block starts
    int row_start = by * blockDim.y;  // Each block processes multiple rows
    int col_start = bx * blockDim.x * ELEMENTS_PER_THREAD;  // Each block processes multiple columns

    // Thread's row in block and global row
    int row_in_block = tx / blockDim.x;
    int col_in_block = tx % blockDim.x;
    int row = row_start + row_in_block;

    // This thread computes multiple columns
    float sums[ELEMENTS_PER_THREAD];
    for (int i = 0; i < ELEMENTS_PER_THREAD; i++) {
        sums[i] = 0.0f;
    }

    // Iterate over K dimension (32 elements - small!)
    for (int k = 0; k < K; k++) {
        float a_val = (row < M) ? A[row * K + k] : 0.0f;

        // Manually unroll for the 4 columns
        #pragma unroll
        for (int i = 0; i < ELEMENTS_PER_THREAD; i++) {
            int col = col_start + col_in_block * ELEMENTS_PER_THREAD + i;
            if (row < M && col < N) {
                sums[i] += a_val * B[k * N + col];
            }
        }
    }

    // Store results
    #pragma unroll
    for (int i = 0; i < ELEMENTS_PER_THREAD; i++) {
        int col = col_start + col_in_block * ELEMENTS_PER_THREAD + i;
        if (row < M && col < N) {
            C[row * N + col] = sums[i];
        }
    }
}

// Simpler version - each thread handles one output but better memory pattern
__global__ void tall_skinny_matmul_kernel_simple(
    const float* A, const float* B, float* C,
    int M, int K, int N) {

    const int COLS_PER_THREAD = 8;

    int row = blockIdx.x * blockDim.x + threadIdx.x;
    int col_base = blockIdx.y * blockDim.y * COLS_PER_THREAD;

    float sums[COLS_PER_THREAD];
    for (int i = 0; i < COLS_PER_THREAD; i++) {
        sums[i] = 0.0f;
    }

    if (row < M) {
        const float* a_row = &A[row * K];

        for (int k = 0; k < K; k++) {
            float a_val = a_row[k];
            const float* b_row = &B[k * N];

            #pragma unroll
            for (int i = 0; i < COLS_PER_THREAD; i++) {
                int col = col_base + threadIdx.y * COLS_PER_THREAD + i;
                if (col < N) {
                    sums[i] += a_val * b_row[col];
                }
            }
        }

        #pragma unroll
        for (int i = 0; i < COLS_PER_THREAD; i++) {
            int col = col_base + threadIdx.y * COLS_PER_THREAD + i;
            if (col < N) {
                C[row * N + col] = sums[i];
            }
        }
    }
}

