cross_entropy_cpp_source = """
#include <hip/hip_runtime.h>

#define BLOCK_SIZE 256
#define SAMPLES_PER_BLOCK 8

__device__ float warp_reduce_max(float val) {
    val = max(val, __shfl_down(val, 16));
    val = max(val, __shfl_down(val, 8));
    val = max(val, __shfl_down(val, 4));
    val = max(val, __shfl_down(val, 2));
    val = max(val, __shfl_down(val, 1));
    return val;
}

__device__ float warp_reduce_sum(float val) {
    val += __shfl_down(val, 16);
    val += __shfl_down(val, 8);
    val += __shfl_down(val, 4);
    val += __shfl_down(val, 2);
    val += __shfl_down(val, 1);
    return val;
}

__global__ void cross_entropy_kernel(
    const float* __restrict__ predictions,
    const int64_t* __restrict__ targets,
    float* __restrict__ losses,
    int batch_size,
    int num_classes
) {
    int block_samples_base = blockIdx.x * SAMPLES_PER_BLOCK;
    int sample_idx_in_block = threadIdx.x % SAMPLES_PER_BLOCK;
    int warps_per_sample = blockDim.x / SAMPLES_PER_BLOCK / 32;
    int warp_id = threadIdx.x / 32;
    int sample_warp_id = warp_id % warps_per_sample;
    int lane_id = threadIdx.x % 32;

    int sample_idx = block_samples_base + sample_idx_in_block;

    __shared__ float sample_data[SAMPLES_PER_BLOCK][2];  // [max_val, sum_exp]
    __shared__ int sample_targets[SAMPLES_PER_BLOCK];
    __shared__ float sample_preds[SAMPLES_PER_BLOCK];

    // Initialize shared memory
    if (lane_id < 2) {
        sample_data[sample_idx_in_block][lane_id] = (lane_id == 0) ? -INFINITY : 0.0f;
    }
    if (lane_id == 0) {
        if (sample_idx < batch_size) {
            sample_targets[sample_idx_in_block] = targets[sample_idx];
            const float* preds = predictions + sample_idx * num_classes;
            sample_preds[sample_idx_in_block] = preds[sample_targets[sample_idx_in_block]];
        } else {
            sample_preds[sample_idx_in_block] = 0.0f;
        }
    }
    __syncthreads();

    if (sample_idx >= batch_size) {
        if (sample_idx_in_block == 0 && lane_id == 0) {
            losses[blockIdx.x] = 0.0f;
        }
        return;
    }

    const float* preds = predictions + sample_idx * num_classes;

    // Warp-level reduction of max
    float max_val = -INFINITY;
    for (int c = sample_warp_id * 32 + lane_id; c < num_classes; c += warps_per_sample * 32) {
        max_val = fmaxf(max_val, preds[c]);
    }
    max_val = warp_reduce_max(max_val);

    // Store max for the sample
    if (lane_id == 0) {
        atomicMax(&sample_data[sample_idx_in_block][0], max_val);
    }
    __syncthreads();

    max_val = sample_data[sample_idx_in_block][0];

    // Warp-level reduction of sum_exp
    float sum_exp = 0.0f;
    for (int c = sample_warp_id * 32 + lane_id; c < num_classes; c += warps_per_sample * 32) {
        sum_exp += expf(preds[c] - max_val);
    }
    sum_exp = warp_reduce_sum(sum_exp);

    // Store sum for the sample
    if (lane_id == 0) {
        atomicAdd(&sample_data[sample_idx_in_block][1], sum_exp);
    }
    __syncthreads();

    sum_exp = sample_data[sample_idx_in_block][1];

    // Write result
    if (sample_idx_in_block == 0 && lane_id == 0) {
        float block_loss = 0.0f;
        for (int i = 0; i < SAMPLES_PER_BLOCK; i++) {
            if (block_samples_base + i < batch_size) {
                float s_max = sample_data[i][0];
                float s_sum = sample_data[i][1];
                float s_pred = sample_preds[i];
                block_loss += (-s_pred + s_max + logf(s_sum));
            }
        }
        losses[blockIdx.x] = block_loss;
    }
}

__global__ void reduce_mean_kernel(
    const float* __restrict__ block_losses,
    float* __restrict__ mean_loss,
    int batch_size
) {
    extern __shared__ float smem[];
    int tid = threadIdx.x;
    int i = blockIdx.x * blockDim.x + tid;

    smem[tid] = (i < blockDim.x) ? block_losses[i] : 0.0f;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            smem[tid] += smem[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        mean_loss[0] = smem[0] / batch_size;
    }
}

torch::Tensor cross_entropy_hip(torch::Tensor predictions, torch::Tensor targets) {
    int batch_size = predictions.size(0);
    int num_classes = predictions.size(1);

    int num_blocks = (batch_size + SAMPLES_PER_BLOCK - 1) / SAMPLES_PER_BLOCK;
    const int threads_per_block = 256;

    auto block_losses = torch::zeros({num_blocks}, predictions.options());

    cross_entropy_kernel<<<num_blocks, threads_per_block>>>(
        predictions.data_ptr<float>(),
        targets.data_ptr<int64_t>(),
        block_losses.data_ptr<float>(),
        batch_size,
        num_classes
    );

    auto mean_loss = torch::zeros({1}, predictions.options());
    reduce_mean_kernel<<<1, 256, 256 * sizeof(float)>>>(
        block_losses.data_ptr<float>(),
        mean_loss.data_ptr<float>(),
        batch_size
    );

    return mean_loss;
}
"""

cross_entropy_module = load_inline(
    name="cross_entropy_loss",
    cpp_sources=cross_entropy_cpp_source,
    functions=["cross_entropy_hip"],
    verbose=True,
)


class ModelNew(nn.Module):
    """
    A model that computes Cross Entropy Loss for multi-class classification tasks
    using an optimized HIP kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.cross_entropy = cross_entropy_module

    def forward(self, predictions, targets):
        return self.cross_entropy.cross_entropy_hip(predictions, targets)

