matmul_hip_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

#define TILE_SIZE 32
#define VEC_WIDTH 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int K, int N) {
    // Each thread computes 4x4 output elements
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Thread i computes multiple output elements
    int row0 = by * TILE_SIZE + ty;
    int row1 = row0 + (TILE_SIZE / 2);

    int col0 = bx * TILE_SIZE + tx;
    int col1 = col0 + (TILE_SIZE / 2);

    float C00 = 0.0f, C01 = 0.0f, C02 = 0.0f, C03 = 0.0f;
    float C10 = 0.0f, C11 = 0.0f, C12 = 0.0f, C13 = 0.0f;

    int num_tiles = (K + TILE_SIZE - 1) / TILE_SIZE;

    for (int t = 0; t < num_tiles; ++t) {
        // Load A tile with coalesced access
        int a_col = t * TILE_SIZE + (tx / VEC_WIDTH) * VEC_WIDTH + ty;
        int a_row = (tx % VEC_WIDTH) * (TILE_SIZE / VEC_WIDTH);
        int actual_row = by * TILE_SIZE + a_row;

        if (actual_row < M && a_col < K) {
            As[a_row][ty + (tx / VEC_WIDTH) * VEC_WIDTH] = A[actual_row * K + a_col];
        } else {
            As[a_row][ty + (tx / VEC_WIDTH) * VEC_WIDTH] = 0.0f;
        }

        // Load B tile with coalesced access
        int b_row = t * TILE_SIZE + (tx / VEC_WIDTH) * VEC_WIDTH + ty;
        int b_col = (tx % VEC_WIDTH) * (TILE_SIZE / VEC_WIDTH);
        int actual_col = bx * TILE_SIZE + b_col;

        if (b_row < K && actual_col < N) {
            Bs[ty + (tx / VEC_WIDTH) * VEC_WIDTH][b_col] = B[b_row * N + actual_col];
        } else {
            Bs[ty + (tx / VEC_WIDTH) * VEC_WIDTH][b_col] = 0.0f;
        }

        __syncthreads();

        // Compute 4 accumulators per thread
        for (int k = 0; k < TILE_SIZE; ++k) {
            float A0 = As[ty][k];
            float A1 = As[ty + 16][k];

            float B0 = Bs[k][tx];
            float B1 = Bs[k][tx + 16];

            C00 += A0 * B0;
            C01 += A0 * B1;
            C10 += A1 * B0;
            C11 += A1 * B1;
        }

        __syncthreads();
    }

    // Write results with coalescing
    int write_col = bx * TILE_SIZE + tx;
    if (row0 < M && write_col < N) {
        C[row0 * N + write_col] = C00;
    }
    write_col += 16;
    if (row0 < M && write_col < N) {
        C[row0 * N + write_col] = C01;
    }

    write_col = bx * TILE_SIZE + tx;
    if (row1 < M && write_col < N) {
        C[row1 * N + write_col] = C10;
    }
    write_col += 16;
    if (row1 < M && write_col < N) {
        C[row1 * N + write_col] = C11;
    }
}

torch::Tensor matmul_hip(torch::Tensor A, torch::Tensor B) {
    auto M = A.size(0);
    auto K = A.size(1);
    auto N = B.size(1);

    auto C = torch::zeros({M, N}, A.options());

    dim3 block(16, 16);
    dim3 grid((N + 31) / 32, (M + 31) / 32);

    hipLaunchKernelGGL(HIP_KERNEL_NAME(matmul_kernel), grid, block, 0, 0, 
                       A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, K, N);

    return C;
}
"""

matmul_module = load_inline(
    name="matmul_optimized",
    cpp_sources=matmul_hip_source,
    functions=["matmul_hip"],
    verbose=True,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul = matmul_module

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        if not A.is_cuda:
            A = A.cuda()
        if not B.is_cuda:
            B = B.cuda()

        # Use FP32 precision
        A = A.float()
        B = B.float()

        return self.matmul.matmul_hip(A, B)

import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

cross_entropy_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void cross_entropy_kernel(
    const float* __restrict__ predictions,
    const int64_t* __restrict__ targets,
    float* __restrict__ loss,
    int batch_size,
    int num_classes
) {
    extern __shared__ float sdata[];

    int batch_idx = blockIdx.x * blockDim.x + threadIdx.x;
    int lane_id = threadIdx.x % 32;

    if (batch_idx >= batch_size) {
        sdata[threadIdx.x] = 0.0f;
        __syncthreads();
        return;
    }

    const float* preds = predictions + batch_idx * num_classes;
    int target_idx = targets[batch_idx];
    float target_pred = preds[target_idx];

    // Find max for numerical stability
    float max_val = -INFINITY;
    for (int c = lane_id; c < num_classes; c += 32) {
        max_val = fmaxf(max_val, preds[c]);
    }

    // Warp reduce max
    max_val = max(max_val, __shfl_down(max_val, 16));
    max_val = max(max_val, __shfl_down(max_val, 8));
    max_val = max(max_val, __shfl_down(max_val, 4));
    max_val = max(max_val, __shfl_down(max_val, 2));
    max_val = max(max_val, __shfl_down(max_val, 1));
    max_val = __shfl(max_val, 0);

    // Compute sum of exp
    float sum_exp = 0.0f;
    for (int c = lane_id; c < num_classes; c += 32) {
        sum_exp += expf(preds[c] - max_val);
    }

    // Warp reduce sum
    sum_exp += __shfl_down(sum_exp, 16);
    sum_exp += __shfl_down(sum_exp, 8);
    sum_exp += __shfl_down(sum_exp, 4);
    sum_exp += __shfl_down(sum_exp, 2);
    sum_exp += __shfl_down(sum_exp, 1);
    sum_exp = __shfl(sum_exp, 0);

    // Cross entropy for this sample
    float ce = -target_pred + max_val + logf(sum_exp);

    sdata[threadIdx.x] = ce;
    __syncthreads();

    // Block reduction
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            sdata[threadIdx.x] += sdata[threadIdx.x + s];
        }
        __syncthreads();
    }

    // Atomic add to global loss
    if (threadIdx.x == 0) {
        atomicAdd(loss, sdata[0]);
    }
}

torch::Tensor cross_entropy_hip(torch::Tensor predictions, torch::Tensor targets) {
    int batch_size = predictions.size(0);
    int num_classes = predictions.size(1);

    const int block_size = 256;
    const int num_blocks = (batch_size + block_size - 1) / block_size;

    auto loss = torch::zeros({1}, predictions.options());
    loss.fill_(0.0f);

    cross_entropy_kernel<<<num_blocks, block_size, block_size * sizeof(float)>>>(
        predictions.data_ptr<float>(),
        targets.data_ptr<int64_t>(),
        loss.data_ptr<float>(),
        batch_size,
        num_classes
    );

    // Divide by batch_size to get mean
    return loss.div_(batch_size);
}
"""

cross_entropy_module = load_inline(
    name="cross_entropy_loss",
    cpp_sources=cross_entropy_cpp_source,
    functions=["cross_entropy_hip"],
    verbose=True,
)


