import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

matmul_cpp_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

// Wavefront-based matrix multiplication for small K
// Each wavefront computes a tile of the output matrix
__global__ void tall_skinny_matmul_wavefront(
    const float* A, const float* B, float* C,
    int M, int K, int N) {

    // Wavefront size is 64 on AMD GPUs
    const int WF_SIZE = 64;

    // Each wavefront processes a 64x64 tile
    int row_start = blockIdx.x * 64;
    int col_start = blockIdx.y * 64;

    int lane_id = threadIdx.x % WF_SIZE;
    int wave_id = threadIdx.x / WF_SIZE;

    // Local accumulators in registers
    float accum[64];
    for (int i = 0; i < 64; i++) {
        accum[i] = 0.0f;
    }

    // Each thread in wavefront computes a row
    int my_row = row_start + lane_id;

    // Vectorized load of A row (K=32, can load all at once)
    float a_row[32];
    if (my_row < M) {
        #pragma unroll
        for (int k = 0; k < 32; k++) {
            a_row[k] = A[my_row * K + k];
        }
    }

    // Compute for this row against all columns in tile
    if (my_row < M) {
        for (int k = 0; k < K; k++) {
            float a_val = a_row[k];

            // Broadcast a_val across wavefront and compute dot products
            // Each thread in wavefront handles one column
            int col = col_start + (threadIdx.x % 64);
            if (col < N) {
                float b_val = B[k * N + col];
                // Use shuffle to accumulate results from wavefront
                float sum = a_val * b_val;

                // Reduction across lanes to get final result
                #pragma unroll
                for (int offset = 32; offset > 0; offset >>= 1) {
                    float other = __builtin_amdgcn_ds_faddf(sum, offset, __builtin_amdgcn_wave_id(), false, true);
                    sum += other;
                }

                if (lane_id == 0) {
                    int result_row = row_start + (threadIdx.x / 64);
                    int result_col = col_start + (threadIdx.x % 64);
                    if (result_row < M && result_col < N) {
                        C[result_row * N + result_col] = sum;
                    }
                }
            }
        }
    }
}

