__global__ void tall_skinny_matmul_rowwise(
    const float* A, const float* B, float* C,
    int M, int K, int N) {

    int row = blockIdx.x;
    int col_base = blockIdx.y * 256;

    float sums[256];
    for (int i = 0; i < 256; i++) {
        sums[i] = 0.0f;
    }

    if (row < M) {
        // Load row of A into registers
        float a_vals[32];
        #pragma unroll
        for (int k = 0; k < 32; k++) {
            a_vals[k] = A[row * 32 + k];
        }

        // Compute against all columns
        for (int k = 0; k < 32; k++) {
            float a_val = a_vals[k];
            const float* b_row = &B[k * N];

            #pragma unroll
            for (int j = 0; j < 256; j++) {
                int col = col_base + j;
                if (col < N) {
                    sums[j] += a_val * b_row[col];
                }
            }
        }

        // Write results
        #pragma unroll
        for (int j = 0; j < 256; j++) {
            int col = col_base + j;
            if (col < N) {
                C[row * N + col] = sums[j];
            }
        }
    }
}

