    dim3 gridDim((N + TILE_SIZE - 1) / TILE_SIZE, (M + TILE_SIZE - 1) / TILE_SIZE, batch_size);

    batched_matmul_tiled_kernel<<<gridDim, blockDim>>>(
        A.data_ptr<float>(),
